1	package main
2	
3	import (
4		"errors"
5		"fmt"
6		"math"
7		"math/big"
8		"math/bits"
9		"strconv"
10	)
11	
12	// 金额、单价、数量均使用有符号 64 位整数（金额单位：人民币分），
13	// 全程整数运算，不经过浮点数。
14	
15	var errOverflow = errors.New("数量或金额运算超出有符号 64 位整数范围")
16	
17	// mul64 返回 a*b，溢出时返回错误。a、b 均非负。
18	func mul64(a, b int64) (int64, error) {
19		if a < 0 || b < 0 {
20			return 0, errOverflow
21		}
22		if a == 0 || b == 0 {
23			return 0, nil
24		}
25		if a > math.MaxInt64/b {
26			return 0, errOverflow
27		}
28		return a * b, nil
29	}
30	
31	// add64 返回 a+b，溢出时返回错误。a、b 均非负。
32	func add64(a, b int64) (int64, error) {
33		if a < 0 || b < 0 || a > math.MaxInt64-b {
34			return 0, errOverflow
35		}
36		return a + b, nil
37	}
38	
39	// addSigned64 返回 a+b（允许负数），溢出时返回错误。
40	func addSigned64(a, b int64) (int64, error) {
41		if (b > 0 && a > math.MaxInt64-b) || (b < 0 && a < math.MinInt64-b) {
42			return 0, errOverflow
43		}
44		return a + b, nil
45	}
46	
47	// neg64 返回 -a；a 为 math.MinInt64 时无法表示，返回错误。
48	func neg64(a int64) (int64, error) {
49		if a == math.MinInt64 {
50			return 0, errOverflow
51		}
52		return -a, nil
53	}
54	
55	// sumSigned64 精确求和一组有符号 64 位整数（内部按 128 位累加，
56	// 与求和顺序无关），最终结果超出有符号 64 位范围时返回错误。
57	func sumSigned64(vals ...int64) (int64, error) {
58		var hi, lo uint64
59		for _, v := range vals {
60			var carry uint64
61			lo, carry = bits.Add64(lo, uint64(v), 0)
62			// 符号扩展 v 的高位后连同进位一起累加。
63			sign := uint64(0)
64			if v < 0 {
65				sign = math.MaxUint64
66			}
67			hi, _ = bits.Add64(hi, sign, carry)
68		}
69		switch {
70		case hi == 0 && lo <= math.MaxInt64:
71			return int64(lo), nil
72		case hi == math.MaxUint64 && lo >= 1<<63:
73			return int64(lo), nil
74		default:
75			return 0, errOverflow
76		}
77	}
78	
79	// moneyFen 将“分”渲染为人民币金额，如 1234 -> "12.34 元"，5 -> "0.05 元"。
80	func moneyFen(fen int64) string {
81		neg := fen < 0
82		// 用无符号数取绝对值，避免 math.MinInt64 取负溢出。
83		u := uint64(fen)
84		if neg {
85			u = uint64(-(fen + 1)) + 1
86		}
87		s := strconv.FormatUint(u, 10)
88		if len(s) < 3 {
89			s = "00" + s
90			s = s[len(s)-3:]
91		}
92		whole, frac := s[:len(s)-2], s[len(s)-2:]
93		out := whole + "." + frac + " 元"
94		if neg {
95			out = "-" + out
96		}
97		return out
98	}
99	
100	// int128 是有符号 128 位整数（二进制补码：hi 为高 64 位、lo 为低 64 位）。
101	// 单账单的应付/实收/未收余额保证在有符号 64 位内，但跨账期报表的多账单
102	// 合计可能超出有符号 64 位上限，汇总必须精确输出，故用 128 位整数累加；
103	// 全程整数运算，不经过浮点（math/big 仅用于十进制格式化）。
104	type int128 struct {
105		hi int64
106		lo uint64
107	}
108	
109	// int128Of 把有符号 64 位整数符号扩展为 128 位。
110	func int128Of(v int64) int128 {
111		if v < 0 {
112			return int128{hi: -1, lo: uint64(v)}
113		}
114		return int128{hi: 0, lo: uint64(v)}
115	}
116	
117	// add 返回 a+b（二进制补码加法，精确）。账单数量级（每月一张）远不足以
118	// 让合法余额的合计溢出 128 位，故无需溢出检查。
119	func (a int128) add(b int128) int128 {
120		lo, carry := bits.Add64(a.lo, b.lo, 0)
121		hi, _ := bits.Add64(uint64(a.hi), uint64(b.hi), carry)
122		return int128{hi: int64(hi), lo: lo}
123	}
124	
125	// neg 返回 -a（二进制补码取负）。
126	func (a int128) neg() int128 {
127		lo, carry := bits.Add64(^a.lo, 1, 0)
128		hi, _ := bits.Add64(uint64(^a.hi), 0, carry)
129		return int128{hi: int64(hi), lo: lo}
130	}
131	
132	// sub 返回 a-b。
133	func (a int128) sub(b int128) int128 { return a.add(b.neg()) }
134	
135	// big 转换为 big.Int 以便十进制格式化（仅用于输出，不参与计算）。
136	func (a int128) big() *big.Int {
137		v := new(big.Int).SetInt64(a.hi)
138		v.Lsh(v, 64)
139		return v.Add(v, new(big.Int).SetUint64(a.lo))
140	}
141	
142	func (a int128) String() string { return a.big().String() }
143	
144	// moneyFen128 将 128 位“分”渲染为人民币金额，规则与 moneyFen 相同。
145	func moneyFen128(fen int128) string {
146		b := fen.big()
147		neg := b.Sign() < 0
148		if neg {
149			b.Neg(b)
150		}
151		whole, frac := new(big.Int).QuoRem(b, big.NewInt(100), new(big.Int))
152		out := fmt.Sprintf("%s.%02d 元", whole.String(), frac.Int64())
153		if neg {
154			out = "-" + out
155		}
156		return out
157	}
