1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// 数据目录布局：
16	//
17	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
18	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
19	//
20	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
21	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
22	
23	const stateVersion = 1
24	
25	type customer struct {
26		ID     string `json:"id"`
27		Name   string `json:"name"`
28		Price  int64  `json:"price_fen"`         // 固定单价，非负整数分，创建后不可修改
29		PlanID string `json:"plan_id,omitempty"` // 绑定的阶梯计费方案标识；空表示固定单价客户，创建后不可变更
30	}
31	
32	// tier 是阶梯计费方案中的一档：Limit 为月累计数量上限（正整数），
33	// 仅最后一档无上限（Limit 为 0）；Price 为该档每单位价格（非负整数分）。
34	type tier struct {
35		Limit int64 `json:"limit"`     // 累计数量上限；0 表示无上限（仅最后一档）
36		Price int64 `json:"price_fen"` // 每单位价格，非负整数分，可升可降
37	}
38	
39	// plan 是按月累计用量的阶梯计费方案：标识唯一非空、名称非空、固定月费
40	// （非负整数分，省略视为 0）与至少一档有序阶梯；月费与规则创建后不可修改。
41	type plan struct {
42		ID         string `json:"id"`
43		Name       string `json:"name"`
44		MonthlyFee int64  `json:"monthly_fee_fen,omitempty"` // 固定月费，非负整数分；每账期收取一次整月，不按天折算
45		Tiers      []tier `json:"tiers"`                     // 至少一档；有限上限严格递增，最后一档无上限
46	}
47	
48	type usageRecord struct {
49		ID         string `json:"id"`
50		CustomerID string `json:"customer_id"`
51		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
52		Quantity   int64  `json:"quantity"`
53	}
54	
55	// lineSegment 是阶梯计费下一条用量记录落入某一档的分段：数量与小计；
56	// 该档单价由账单保存的方案规则按档位序号取得。
57	type lineSegment struct {
58		Tier     int   `json:"tier"`     // 档位序号（0 起，对应账单保存的方案规则）
59		Quantity int64 `json:"quantity"` // 落入本档的数量
60		Fee      int64 `json:"fee_fen"`  // 本分段小计（数量 × 该档单价）
61	}
62	
63	// tierTotal 是阶梯账单中某一档的合计数量与金额（与 PlanTiers 顺序对齐）。
64	type tierTotal struct {
65		Quantity int64 `json:"quantity"`
66		Fee      int64 `json:"fee_fen"`
67	}
68	
69	type billLine struct {
70		UsageID  string        `json:"usage_id"`
71		Time     string        `json:"time"`
72		Quantity int64         `json:"quantity"`
73		LineFee  int64         `json:"line_fee_fen"`
74		Segments []lineSegment `json:"segments,omitempty"` // 阶梯账单：本条用量的跨档分段
75	}
76	
77	type bill struct {
78		ID         string      `json:"id"`
79		CustomerID string      `json:"customer_id"`
80		Month      string      `json:"month"`                 // YYYY-MM（UTC）
81		Pricing    string      `json:"pricing,omitempty"`     // 计价类型：空或 fixed 为固定单价；tiered 为阶梯计费
82		PlanID     string      `json:"plan_id,omitempty"`     // 阶梯账单：方案标识
83		PlanName   string      `json:"plan_name,omitempty"`   // 阶梯账单：方案名称（快照）
84		PlanTiers  []tier      `json:"plan_tiers,omitempty"`  // 阶梯账单：完整方案规则（快照）
85		TierTotals []tierTotal `json:"tier_totals,omitempty"` // 阶梯账单：各档实际数量与金额合计
86		// 阶梯账单：实际收取的固定月费快照（分），非负；按账期有效方案收取一次
87		// 整月，不计入总数量、各档金额或逐条小计。固定单价账单恒为 0。
88		MonthlyFee int64      `json:"monthly_fee_fen,omitempty"`
89		TotalQty   int64      `json:"total_quantity"`
90		UnitPrice  int64      `json:"unit_price_fen"` // 固定单价账单的单价；阶梯账单恒为 0（不伪造统一单价）
91		TotalFee   int64      `json:"total_fee_fen"`
92		Lines      []billLine `json:"lines"`
93		CreatedAt  string     `json:"created_at"`
94	}
95	
96	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
97	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
98	type adjustment struct {
99		ID           string `json:"id"`
100		CustomerID   string `json:"customer_id"`
101		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
102		Amount       int64  `json:"amount_fen"`
103		Reason       string `json:"reason"`
104		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
105		CreatedAt    string `json:"created_at"`
106		Revoked      bool   `json:"revoked"`
107		RevokeReason string `json:"revoke_reason,omitempty"`
108		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
109		RevokedAt    string `json:"revoked_at,omitempty"`
110	}
111	
112	// paymentAllocation 是一笔收款在某个已结算月份上的分配（正整数分）。
113	type paymentAllocation struct {
114		Month  string `json:"month"`      // YYYY-MM（UTC），须已有账单
115		Amount int64  `json:"amount_fen"` // 正整数分
116	}
117	
118	// payment 是一笔实收登记：同一客户的一笔汇款（总额 Total 分）按分配列表
119	// 计入一个或多个已结算月份；单账单收款视为只有一项分配的汇款。
120	// 记录一旦写入永不删除；撤销只是追加撤销信息，整笔撤销全部分配并保留
121	// 原记录，撤销后该笔不再计入实收，也不会因重放而恢复。
122	type payment struct {
123		ID           string              `json:"id"`
124		CustomerID   string              `json:"customer_id"`
125		Total        int64               `json:"total_fen"` // 收款总额，正整数分，等于分配合计
126		Note         string              `json:"note"`
127		Allocations  []paymentAllocation `json:"allocations"` // 至少一项，月份不重复，按月份升序保存
128		Seq          int64               `json:"seq"`         // 全局递增操作序号，决定历史展示顺序
129		CreatedAt    string              `json:"created_at"`
130		Revoked      bool                `json:"revoked"`
131		RevokeReason string              `json:"revoke_reason,omitempty"`
132		RevokeSeq    int64               `json:"revoke_seq,omitempty"`
133		RevokedAt    string              `json:"revoked_at,omitempty"`
134	}
135	
136	// UnmarshalJSON 兼容旧版单账单收款格式（month + amount_fen，无 allocations）：
137	// 读入时归一化为一项分配，之后一律按新格式写回。
138	func (p *payment) UnmarshalJSON(data []byte) error {
139		type plain payment // 去掉方法，避免递归
140		var raw struct {
141			plain
142			Month  string `json:"month"`      // 旧格式：所属账单月份
143			Amount int64  `json:"amount_fen"` // 旧格式：收款金额
144		}
145		if err := json.Unmarshal(data, &raw); err != nil {
146			return err
147		}
148		*p = payment(raw.plain)
149		if len(p.Allocations) == 0 && raw.Month != "" {
150			p.Allocations = []paymentAllocation{{Month: raw.Month, Amount: raw.Amount}}
151			p.Total = raw.Amount
152		}
153		return nil
154	}
155	
156	// amountFor 返回该收款在指定月份的分配金额；无分配时为 0。
157	func (p *payment) amountFor(month string) int64 {
158		for _, al := range p.Allocations {
159			if al.Month == month {
160				return al.Amount
161			}
162		}
163		return 0
164	}
165	
166	// correction 是对一笔未撤销收款的分配更正：客户、总额、备注、原账单及
167	// 应付不变，仅把该笔收款当前生效的分配整体替换为完整新分配。记录一旦写入
168	// 永不删除；首次登记内容永久保留，bill pay / bill remit 仍按原始分配判重，
169	// 更正不影响收款身份。可连续更正，每次以当时最新分配为起点。
170	type correction struct {
171		ID          string              `json:"id"`
172		PaymentID   string              `json:"payment_id"` // 目标收款标识
173		Reason      string              `json:"reason"`
174		Allocations []paymentAllocation `json:"allocations"` // 完整新分配，至少一项，月份不重复，按月份升序保存
175		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款及其撤销共用
176		CreatedAt   string              `json:"created_at"`
177	}
178	
179	// refund 是对一笔已登记收款的部分退款登记：从该收款当前最新分配涉及的
180	// 月份中实际退回资金，各月退款金额为正整数分，累计不得超过该笔在该月的
181	// 分配。记录一旦写入永不删除、不可撤销；首次退款后该收款的最新分配固定，
182	// 不得再新增分配更正或整笔撤销。退款标识与收款、调整、更正标识命名空间
183	// 相互独立，可同名。
184	type refund struct {
185		ID          string              `json:"id"`
186		PaymentID   string              `json:"payment_id"` // 目标收款标识
187		Reason      string              `json:"reason"`
188		Allocations []paymentAllocation `json:"allocations"` // 各月退款金额，至少一项，月份不重复，按月份升序保存
189		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款/更正及其撤销共用
190		CreatedAt   string              `json:"created_at"`
191	}
192	
193	// planChange 是阶梯客户的一次按月生效的方案变更：自生效月（UTC 自然月，
194	// 含）起改用目标方案，直到下一次变更；生效月之前的月份不受影响。记录一旦
195	// 写入永不修改或删除；变更不产生账后流水事件，也不占用全局操作序号。
196	type planChange struct {
197		CustomerID string `json:"customer_id"`
198		Month      string `json:"month"`   // YYYY-MM（UTC），生效月（含）
199		PlanID     string `json:"plan_id"` // 目标阶梯计费方案标识
200		Reason     string `json:"reason"`
201		CreatedAt  string `json:"created_at"`
202	}
203	
204	// suspension 是阶梯客户的一段按月暂停区间：自起月（UTC 自然月，含）起
205	// 暂停服务，直到结束月（不含），即 [StartMonth, EndMonth) 覆盖的自然月。
206	// 暂停月不接收用量、不产生月费账单；区间可相接（相接视为连续暂停）但不得
207	// 重叠。记录一旦写入永不修改或删除；暂停不产生账后流水事件，也不占用全局
208	// 操作序号。固定单价客户不适用暂停。
209	type suspension struct {
210		CustomerID string `json:"customer_id"`
211		StartMonth string `json:"start_month"` // YYYY-MM（UTC），暂停起月（含）
212		EndMonth   string `json:"end_month"`   // YYYY-MM（UTC），结束月（不含），严格晚于起月
213		Reason     string `json:"reason"`
214		CreatedAt  string `json:"created_at"`
215	}
216	
217	// withdrawal 是一条用量记录的撤回标记：原记录（客户、时间、数量、标识）永久
218	// 保留在 Usage 中，撤回只追加状态与原因，用于纠正误导入的记录。撤回不可恢复、
219	// 标识不可复用；已撤回用量不参与结算、方案变更预检与暂停区间冲突检查，但相同
220	// 内容的重放仍按原记录判重跳过。撤回只作用于该条记录，不占用全局操作序号。
221	type withdrawal struct {
222		UsageID   string `json:"usage_id"` // 撤回的用量标识（与键一致）
223		Reason    string `json:"reason"`   // 撤回原因，非空
224		CreatedAt string `json:"created_at"`
225	}
226	
227	type state struct {
228		Version     int                     `json:"version"`
229		Customers   map[string]*customer    `json:"customers"`
230		Plans       map[string]*plan        `json:"plans"`                 // 全局唯一方案标识 -> 阶梯计费方案
231		Usage       map[string]*usageRecord `json:"usage"`                 // 全局唯一用量标识 -> 记录
232		Bills       map[string]*bill        `json:"bills"`                 // 客户 + "|" + 月份 -> 账单
233		Adjustments map[string]*adjustment  `json:"adjustments"`           // 全局唯一调整标识 -> 记录
234		Payments    map[string]*payment     `json:"payments"`              // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
235		Corrections map[string]*correction  `json:"corrections"`           // 全局唯一更正标识 -> 记录（与收款、调整标识相互独立，可同名）
236		Refunds     map[string]*refund      `json:"refunds,omitempty"`     // 全局唯一退款标识 -> 记录（与收款、调整、更正标识相互独立，可同名；不可撤销）
237		PlanChanges map[string]*planChange  `json:"plan_changes"`          // 客户 + "|" + 生效月 -> 方案变更（按生效月递增追加，不可改写）
238		Suspensions map[string]*suspension  `json:"suspensions,omitempty"` // 客户 + "|" + 起月 -> 暂停区间（不可改写）
239		Withdrawals map[string]*withdrawal  `json:"withdrawals,omitempty"` // 用量标识 -> 撤回标记（不可恢复，标识不可复用）
240		NextSeq     int64                   `json:"next_seq"`              // 已分配的最大操作序号（调整/收款/更正/退款及其撤销共用；方案变更、暂停与用量撤回不占用）
241		path        string                  `json:"-"`
242	}
243	
244	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
245	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
246	func loadStore(dir string) (*state, error) {
247		p := filepath.Join(dir, "state.json")
248		data, err := os.ReadFile(p)
249		if err != nil {
250			if errors.Is(err, os.ErrNotExist) {
251				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
252					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
253				}
254				return newState(p), nil
255			}
256			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
257		}
258	
259		var s state
260		dec := json.NewDecoder(bytes.NewReader(data))
261		if err := dec.Decode(&s); err != nil {
262			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
263		}
264		// 拒绝完整 JSON 之后的任何非空白内容（包括单独的 ] 或 }），避免静默
265		// 吞掉异常数据；合法尾随空白仍可读取。
266		if off := dec.InputOffset(); off < int64(len(data)) {
267			if strings.TrimSpace(string(data[off:])) != "" {
268				return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
269			}
270		}
271		if err := s.validate(); err != nil {
272			return nil, fmt.Errorf("数据文件已损坏: %w", err)
273		}
274		// 旧版本数据文件没有 plans/adjustments/payments/corrections/refunds/
275		// plan_changes/suspensions/withdrawals/next_seq 字段：视为零方案、零调整、
276		// 零实收、零更正、零退款、零方案变更、零暂停、零撤回（全部用量有效）。
277		if s.Plans == nil {
278			s.Plans = map[string]*plan{}
279		}
280		if s.Adjustments == nil {
281			s.Adjustments = map[string]*adjustment{}
282		}
283		if s.Payments == nil {
284			s.Payments = map[string]*payment{}
285		}
286		if s.Corrections == nil {
287			s.Corrections = map[string]*correction{}
288		}
289		if s.Refunds == nil {
290			s.Refunds = map[string]*refund{}
291		}
292		if s.PlanChanges == nil {
293			s.PlanChanges = map[string]*planChange{}
294		}
295		if s.Suspensions == nil {
296			s.Suspensions = map[string]*suspension{}
297		}
298		if s.Withdrawals == nil {
299			s.Withdrawals = map[string]*withdrawal{}
300		}
301		s.path = p
302		return &s, nil
303	}
304	
305	func newState(p string) *state {
306		return &state{
307			Version:     stateVersion,
308			Customers:   map[string]*customer{},
309			Plans:       map[string]*plan{},
310			Usage:       map[string]*usageRecord{},
311			Bills:       map[string]*bill{},
312			Adjustments: map[string]*adjustment{},
313			Payments:    map[string]*payment{},
314			Corrections: map[string]*correction{},
315			Refunds:     map[string]*refund{},
316			PlanChanges: map[string]*planChange{},
317			Suspensions: map[string]*suspension{},
318			Withdrawals: map[string]*withdrawal{},
319			path:        p,
320		}
321	}
322	
323	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
324	func (s *state) validate() error {
325		if s.Version != stateVersion {
326			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
327		}
328		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
329			return errors.New("缺少必要的数据节")
330		}
331		for id, p := range s.Plans {
332			if p == nil {
333				return fmt.Errorf("方案 %q 的数据为空", id)
334			}
335			if p.ID != id {
336				return fmt.Errorf("方案标识不一致: 键 %q / 记录 %q", id, p.ID)
337			}
338			if err := validatePlanRules(p); err != nil {
339				return err
340			}
341		}
342		for id, c := range s.Customers {
343			if c == nil {
344				return fmt.Errorf("客户 %q 的数据为空", id)
345			}
346			if c.ID != id {
347				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
348			}
349			if c.ID == "" || c.Name == "" {
350				return fmt.Errorf("客户 %q 的标识或名称为空", id)
351			}
352			if c.Price < 0 {
353				return fmt.Errorf("客户 %q 单价为负", id)
354			}
355			if c.PlanID != "" {
356				if _, ok := s.Plans[c.PlanID]; !ok {
357					return fmt.Errorf("客户 %q 绑定了不存在的方案 %q", id, c.PlanID)
358				}
359			}
360		}
361		// 方案变更：键、客户（须为绑定阶梯方案的客户）、目标方案、生效月与
362		// 原因都必须自洽；同一客户的变更生效月由键保证唯一。
363		for key, ch := range s.PlanChanges {
364			if ch == nil {
365				return fmt.Errorf("方案变更 %q 的数据为空", key)
366			}
367			if planChangeKey(ch.CustomerID, ch.Month) != key {
368				return fmt.Errorf("方案变更键不一致: 键 %q / 客户月份 %s|%s", key, ch.CustomerID, ch.Month)
369			}
370			c, ok := s.Customers[ch.CustomerID]
371			if !ok {
372				return fmt.Errorf("方案变更 %q 引用了不存在的客户 %q", key, ch.CustomerID)
373			}
374			if c.PlanID == "" {
375				return fmt.Errorf("方案变更 %q 的客户 %q 未绑定阶梯方案", key, ch.CustomerID)
376			}
377			if !validMonth(ch.Month) {
378				return fmt.Errorf("方案变更 %q 的生效月无效", key)
379			}
380			if _, ok := s.Plans[ch.PlanID]; !ok {
381				return fmt.Errorf("方案变更 %q 引用了不存在的方案 %q", key, ch.PlanID)
382			}
383			if strings.TrimSpace(ch.Reason) == "" {
384				return fmt.Errorf("方案变更 %q 的原因为空", key)
385			}
386		}
387		for id, u := range s.Usage {
388			if u == nil {
389				return fmt.Errorf("用量 %q 的数据为空", id)
390			}
391			if u.ID != id {
392				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
393			}
394			if u.ID == "" {
395				return errors.New("存在空的用量标识")
396			}
397			if _, ok := s.Customers[u.CustomerID]; !ok {
398				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
399			}
400			if u.Quantity <= 0 {
401				return fmt.Errorf("用量 %q 的数量非正", u.ID)
402			}
403			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
404				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
405			}
406		}
407		// 撤回标记：键与记录一致、目标用量存在（撤回目标失效即损坏）、原因非空。
408		// 原用量记录仍按上面的规则完整校验（格式、正数量、客户存在性），撤回不
409		// 删除或改写原记录。旧文件缺少撤回记录视为全部用量有效（Withdrawals 已
410		// 在载入时补为空表）。
411		for id, w := range s.Withdrawals {
412			if w == nil {
413				return fmt.Errorf("用量 %q 的撤回记录为空", id)
414			}
415			if w.UsageID != id {
416				return fmt.Errorf("撤回记录键不一致: 键 %q / 用量标识 %q", id, w.UsageID)
417			}
418			if w.UsageID == "" {
419				return errors.New("存在空用量标识的撤回记录")
420			}
421			if _, ok := s.Usage[w.UsageID]; !ok {
422				return fmt.Errorf("撤回记录引用了不存在的用量 %q（撤回目标失效）", w.UsageID)
423			}
424			if strings.TrimSpace(w.Reason) == "" {
425				return fmt.Errorf("用量 %q 的撤回原因为空", w.UsageID)
426			}
427		}
428		for key, b := range s.Bills {
429			if b == nil {
430				return fmt.Errorf("账单 %q 的数据为空", key)
431			}
432			if billKey(b.CustomerID, b.Month) != key {
433				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
434			}
435			if _, ok := s.Customers[b.CustomerID]; !ok {
436				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
437			}
438			if !validMonth(b.Month) {
439				return fmt.Errorf("账单 %q 的月份无效", key)
440			}
441			if b.MonthlyFee < 0 {
442				return fmt.Errorf("账单 %q 的月费为负", key)
443			}
444			// 仅月费大于 0 的账单允许空用量明细（无用量也须出账收取月费）。
445			if len(b.Lines) == 0 && b.MonthlyFee == 0 {
446				return fmt.Errorf("账单 %q 没有明细", key)
447			}
448			var qty, fee int64
449			for _, ln := range b.Lines {
450				u, ok := s.Usage[ln.UsageID]
451				if !ok {
452					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
453				}
454				// 已撤回用量不参与结算，账单不得把已撤回记录视为待计费用量。
455				if _, withdrawn := s.Withdrawals[ln.UsageID]; withdrawn {
456					return fmt.Errorf("账单 %q 引用了已撤回的用量 %q", key, ln.UsageID)
457				}
458				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
459					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
460				}
461				if !inMonth(u.Time, b.Month) {
462					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
463				}
464				var err error
465				qty, err = add64(qty, ln.Quantity)
466				if err != nil {
467					return fmt.Errorf("账单 %q 汇总数量溢出", key)
468				}
469				fee, err = add64(fee, ln.LineFee)
470				if err != nil {
471					return fmt.Errorf("账单 %q 汇总金额溢出", key)
472				}
473			}
474			if qty != b.TotalQty {
475				return fmt.Errorf("账单 %q 总数量与明细不符", key)
476			}
477			// 原总金额 = 月费 + 全月用量费；月费不计入逐条用量小计，故明细
478			// 小计之和等于用量费（总金额 − 月费）。月费与总金额均非负，相减
479			// 不会溢出；总金额为负或小于月费时此处必然不符。
480			if usageFee := b.TotalFee - b.MonthlyFee; fee != usageFee {
481				return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费（明细小计合计 %d 分，月费 %d 分，总金额 %d 分）",
482					key, fee, b.MonthlyFee, b.TotalFee)
483			}
484			c := s.Customers[b.CustomerID]
485			switch b.Pricing {
486			case "", "fixed":
487				// 固定单价账单：每条小计必须等于 数量×客户固定单价，且不得
488				// 携带阶梯方案信息、分段或月费。
489				if b.PlanID != "" || b.PlanName != "" || len(b.PlanTiers) > 0 || len(b.TierTotals) > 0 {
490					return fmt.Errorf("账单 %q 是固定单价账单但携带阶梯方案信息", key)
491				}
492				if b.MonthlyFee != 0 {
493					return fmt.Errorf("账单 %q 是固定单价账单但携带月费", key)
494				}
495				for _, ln := range b.Lines {
496					if len(ln.Segments) > 0 {
497						return fmt.Errorf("账单 %q 的明细 %q 携带阶梯分段", key, ln.UsageID)
498					}
499					lf, err := mul64(ln.Quantity, c.Price)
500					if err != nil {
501						return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
502					}
503					if lf != ln.LineFee {
504						return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
505					}
506				}
507				if b.UnitPrice != c.Price {
508					return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
509				}
510			case "tiered":
511				if err := s.validateTieredBill(key, b, c); err != nil {
512					return err
513				}
514			default:
515				return fmt.Errorf("账单 %q 的计价类型 %q 未知", key, b.Pricing)
516			}
517			// 封账期内不得存在游离于账单之外的有效用量（封账后新增被禁止，
518			// 而已入账记录理应全部在明细中）；已撤回用量不计费用，允许存在
519			// 于已封账月份而不进入账单。
520			for _, u := range s.Usage {
521				if _, withdrawn := s.Withdrawals[u.ID]; withdrawn {
522					continue
523				}
524				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
525					found := false
526					for _, ln := range b.Lines {
527						if ln.UsageID == u.ID {
528							found = true
529							break
530						}
531					}
532					if !found {
533						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
534					}
535				}
536			}
537		}
538	
539		// 暂停区间：键、客户（须为绑定阶梯方案的客户）、区间与原因都必须自洽；
540		// 同一客户的区间不得重叠（可以相接）；暂停月内不得存在有效（未撤回）
541		// 用量或账单。
542		// 旧文件缺少暂停记录视为正常服务（Suspensions 已在载入时补为空表）。
543		for key, su := range s.Suspensions {
544			if su == nil {
545				return fmt.Errorf("暂停区间 %q 的数据为空", key)
546			}
547			if suspensionKey(su.CustomerID, su.StartMonth) != key {
548				return fmt.Errorf("暂停区间键不一致: 键 %q / 客户起月 %s|%s", key, su.CustomerID, su.StartMonth)
549			}
550			c, ok := s.Customers[su.CustomerID]
551			if !ok {
552				return fmt.Errorf("暂停区间 %q 引用了不存在的客户 %q", key, su.CustomerID)
553			}
554			if c.PlanID == "" {
555				return fmt.Errorf("暂停区间 %q 的客户 %q 未绑定阶梯方案（固定单价客户不适用暂停）", key, su.CustomerID)
556			}
557			if !validMonth(su.StartMonth) {
558				return fmt.Errorf("暂停区间 %q 的起月无效", key)
559			}
560			if !validMonth(su.EndMonth) || su.EndMonth <= su.StartMonth {
561				return fmt.Errorf("暂停区间 %q 的结束月无效（结束月必须是晚于起月 %s 的 YYYY-MM）", key, su.StartMonth)
562			}
563			if strings.TrimSpace(su.Reason) == "" {
564				return fmt.Errorf("暂停区间 %q 的原因为空", key)
565			}
566		}
567		for customerID := range s.Customers {
568			list := s.suspensionsFor(customerID)
569			for i := 1; i < len(list); i++ {
570				if list[i].StartMonth < list[i-1].EndMonth {
571					return fmt.Errorf("客户 %s 的暂停区间 %s..%s 与 %s..%s 重叠（区间可以相接但不得重叠）",
572						customerID, list[i-1].StartMonth, list[i-1].EndMonth, list[i].StartMonth, list[i].EndMonth)
573				}
574			}
575			for _, su := range list {
576				for _, u := range s.Usage {
577					// 已撤回用量不参与用量冲突判断，可存在于随后暂停的月份。
578					if _, withdrawn := s.Withdrawals[u.ID]; withdrawn {
579						continue
580					}
581					if u.CustomerID == customerID && monthInRange(utcMonth(u.Time), su.StartMonth, su.EndMonth) {
582						return fmt.Errorf("客户 %s 在暂停区间 %s..%s（不含结束月）内存在用量 %q（%s）",
583							customerID, su.StartMonth, su.EndMonth, u.ID, utcMonth(u.Time))
584					}
585				}
586				for _, b := range s.Bills {
587					if b.CustomerID == customerID && monthInRange(b.Month, su.StartMonth, su.EndMonth) {
588						return fmt.Errorf("客户 %s 在暂停区间 %s..%s（不含结束月）内存在账单（月份 %s），暂停月不得封账",
589							customerID, su.StartMonth, su.EndMonth, b.Month)
590					}
591				}
592			}
593		}
594	
595		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
596		// 调整与收款共用同一个全局操作序号池；两者标识命名空间相互独立，
597		// 允许同名，各自判重与撤销。
598		if s.NextSeq < 0 {
599			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
600		}
601		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
602		for id, a := range s.Adjustments {
603			if a == nil {
604				return fmt.Errorf("调整 %q 的数据为空", id)
605			}
606			if a.ID != id {
607				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
608			}
609			if a.ID == "" {
610				return errors.New("存在空的调整标识")
611			}
612			if a.Amount == 0 {
613				return fmt.Errorf("调整 %q 的金额为零", id)
614			}
615			if strings.TrimSpace(a.Reason) == "" {
616				return fmt.Errorf("调整 %q 的原因为空", id)
617			}
618			if !validMonth(a.Month) {
619				return fmt.Errorf("调整 %q 的月份无效", id)
620			}
621			if _, ok := s.Customers[a.CustomerID]; !ok {
622				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
623			}
624			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
625				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
626			}
627			if a.Seq < 1 || a.Seq > s.NextSeq {
628				return fmt.Errorf("调整 %q 的操作序号越界", id)
629			}
630			if prev, dup := seenSeq[a.Seq]; dup {
631				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
632			}
633			seenSeq[a.Seq] = "调整 " + id
634			if a.Revoked {
635				if strings.TrimSpace(a.RevokeReason) == "" {
636					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
637				}
638				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
639					return fmt.Errorf("调整 %q 的撤销序号越界", id)
640				}
641				if prev, dup := seenSeq[a.RevokeSeq]; dup {
642					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
643				}
644				seenSeq[a.RevokeSeq] = "撤销调整 " + id
645			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
646				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
647			}
648		}
649		for id, p := range s.Payments {
650			if p == nil {
651				return fmt.Errorf("收款 %q 的数据为空", id)
652			}
653			if p.ID != id {
654				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
655			}
656			if p.ID == "" {
657				return errors.New("存在空的收款标识")
658			}
659			if p.Total <= 0 {
660				return fmt.Errorf("收款 %q 的总额不是正整数", id)
661			}
662			if strings.TrimSpace(p.Note) == "" {
663				return fmt.Errorf("收款 %q 的备注为空", id)
664			}
665			if _, ok := s.Customers[p.CustomerID]; !ok {
666				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
667			}
668			if len(p.Allocations) == 0 {
669				return fmt.Errorf("收款 %q 没有分配", id)
670			}
671			seenMonths := make(map[string]bool)
672			var sum int64
673			for _, al := range p.Allocations {
674				if !validMonth(al.Month) {
675					return fmt.Errorf("收款 %q 的分配月份 %q 无效", id, al.Month)
676				}
677				if seenMonths[al.Month] {
678					return fmt.Errorf("收款 %q 的分配月份 %s 重复", id, al.Month)
679				}
680				seenMonths[al.Month] = true
681				if al.Amount <= 0 {
682					return fmt.Errorf("收款 %q 在 %s 的分配金额不是正整数", id, al.Month)
683				}
684				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
685					return fmt.Errorf("收款 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
686				}
687				var err error
688				sum, err = add64(sum, al.Amount)
689				if err != nil {
690					return fmt.Errorf("收款 %q 的分配金额汇总溢出: %w", id, err)
691				}
692			}
693			if sum != p.Total {
694				return fmt.Errorf("收款 %q 的分配合计 %d 分与总额 %d 分不一致", id, sum, p.Total)
695			}
696			if p.Seq < 1 || p.Seq > s.NextSeq {
697				return fmt.Errorf("收款 %q 的操作序号越界", id)
698			}
699			if prev, dup := seenSeq[p.Seq]; dup {
700				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
701			}
702			seenSeq[p.Seq] = "收款 " + id
703			if p.Revoked {
704				if strings.TrimSpace(p.RevokeReason) == "" {
705					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
706				}
707				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
708					return fmt.Errorf("收款 %q 的撤销序号越界", id)
709				}
710				if prev, dup := seenSeq[p.RevokeSeq]; dup {
711					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
712				}
713				seenSeq[p.RevokeSeq] = "撤销收款 " + id
714			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
715				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
716			}
717		}
718		// 分配更正记录：标识、目标收款、原因、新分配与序号都必须自洽。
719		// 更正标识与收款、调整标识命名空间相互独立，允许同名。
720		for id, c := range s.Corrections {
721			if c == nil {
722				return fmt.Errorf("更正 %q 的数据为空", id)
723			}
724			if c.ID != id {
725				return fmt.Errorf("更正标识不一致: 键 %q / 记录 %q", id, c.ID)
726			}
727			if c.ID == "" {
728				return errors.New("存在空的更正标识")
729			}
730			p, ok := s.Payments[c.PaymentID]
731			if !ok {
732				return fmt.Errorf("更正 %q 引用了不存在的收款 %q", id, c.PaymentID)
733			}
734			if strings.TrimSpace(c.Reason) == "" {
735				return fmt.Errorf("更正 %q 的原因为空", id)
736			}
737			if len(c.Allocations) == 0 {
738				return fmt.Errorf("更正 %q 没有新分配", id)
739			}
740			seenMonths := make(map[string]bool)
741			var sum int64
742			for _, al := range c.Allocations {
743				if !validMonth(al.Month) {
744					return fmt.Errorf("更正 %q 的分配月份 %q 无效", id, al.Month)
745				}
746				if seenMonths[al.Month] {
747					return fmt.Errorf("更正 %q 的分配月份 %s 重复", id, al.Month)
748				}
749				seenMonths[al.Month] = true
750				if al.Amount <= 0 {
751					return fmt.Errorf("更正 %q 在 %s 的分配金额不是正整数", id, al.Month)
752				}
753				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
754					return fmt.Errorf("更正 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
755				}
756				var err error
757				sum, err = add64(sum, al.Amount)
758				if err != nil {
759					return fmt.Errorf("更正 %q 的分配金额汇总溢出: %w", id, err)
760				}
761			}
762			if sum != p.Total {
763				return fmt.Errorf("更正 %q 的分配合计 %d 分与关联收款 %q 的总额 %d 分不一致", id, sum, c.PaymentID, p.Total)
764			}
765			if c.Seq <= p.Seq || c.Seq > s.NextSeq {
766				return fmt.Errorf("更正 %q 的操作序号越界", id)
767			}
768			if p.Revoked && c.Seq > p.RevokeSeq {
769				return fmt.Errorf("更正 %q 的操作序号晚于关联收款 %q 的撤销序号", id, c.PaymentID)
770			}
771			if prev, dup := seenSeq[c.Seq]; dup {
772				return fmt.Errorf("更正 %q 与 %q 的操作序号重复", id, prev)
773			}
774			seenSeq[c.Seq] = "更正 " + id
775		}
776		// 退款记录：标识、目标收款、原因、各月退款与序号都必须自洽。退款标识与
777		// 收款、调整、更正标识命名空间相互独立，允许同名。退款只作用于未撤销
778		// 收款的最新分配涉及的月份；首次退款后该收款不得再更正或整笔撤销，
779		// 因此全部退款都以当前最新分配为准核验，累计不得超退。旧文件缺少退款
780		// 记录视为无退款（Refunds 已在载入时补为空表）。
781		for id, r := range s.Refunds {
782			if r == nil {
783				return fmt.Errorf("退款 %q 的数据为空", id)
784			}
785			if r.ID != id {
786				return fmt.Errorf("退款标识不一致: 键 %q / 记录 %q", id, r.ID)
787			}
788			if r.ID == "" {
789				return errors.New("存在空的退款标识")
790			}
791			p, ok := s.Payments[r.PaymentID]
792			if !ok {
793				return fmt.Errorf("退款 %q 引用了不存在的收款 %q（退款目标失效）", id, r.PaymentID)
794			}
795			if strings.TrimSpace(r.Reason) == "" {
796				return fmt.Errorf("退款 %q 的原因为空", id)
797			}
798			if len(r.Allocations) == 0 {
799				return fmt.Errorf("退款 %q 没有月份金额清单", id)
800			}
801			current := currentAllocations(s, p)
802			seenMonths := make(map[string]bool)
803			for _, al := range r.Allocations {
804				if !validMonth(al.Month) {
805					return fmt.Errorf("退款 %q 的月份 %q 无效", id, al.Month)
806				}
807				if seenMonths[al.Month] {
808					return fmt.Errorf("退款 %q 的月份 %s 重复", id, al.Month)
809				}
810				seenMonths[al.Month] = true
811				if al.Amount <= 0 {
812					return fmt.Errorf("退款 %q 在 %s 的金额不是正整数", id, al.Month)
813				}
814				if allocAmountFor(current, al.Month) <= 0 {
815					return fmt.Errorf("退款 %q 的月份 %s 不在收款 %q 的最新分配中（仅允许退最新分配涉及的月份）", id, al.Month, r.PaymentID)
816				}
817			}
818			if r.Seq <= p.Seq || r.Seq > s.NextSeq {
819				return fmt.Errorf("退款 %q 的操作序号越界", id)
820			}
821			if prev, dup := seenSeq[r.Seq]; dup {
822				return fmt.Errorf("退款 %q 与 %q 的操作序号重复", id, prev)
823			}
824			seenSeq[r.Seq] = "退款 " + id
825		}
826		// 逐收款核验退款相关约束：已退款的收款不得被整笔撤销；首次退款后不得
827		// 再出现更正（最新分配已固定）；各月累计退款不得超过该笔在该月的最新
828		// 分配（累计超退即余额异常）。
829		for pid, p := range s.Payments {
830			refs := refundsFor(s, pid)
831			if len(refs) == 0 {
832				continue
833			}
834			firstRefundSeq := refs[0].Seq // refundsFor 按序号升序
835			if p.Revoked {
836				return fmt.Errorf("收款 %q 已发生退款（首次退款序号 %d）却又被整笔撤销（序号 %d），操作先后非法", pid, firstRefundSeq, p.RevokeSeq)
837			}
838			for _, c := range s.Corrections {
839				if c.PaymentID == pid && c.Seq > firstRefundSeq {
840					return fmt.Errorf("更正 %q 的序号 %d 晚于收款 %q 的首次退款序号 %d（首次退款后最新分配已固定），操作先后非法", c.ID, c.Seq, pid, firstRefundSeq)
841				}
842			}
843			current := currentAllocations(s, p)
844			totals := make(map[string]int64)
845			for _, r := range refs {
846				for _, al := range r.Allocations {
847					sum, err := add64(totals[al.Month], al.Amount)
848					if err != nil {
849						return fmt.Errorf("收款 %q 在 %s 的累计退款溢出有符号 64 位整数范围，余额异常", pid, al.Month)
850					}
851					totals[al.Month] = sum
852				}
853			}
854			for month, refunded := range totals {
855				if alloc := allocAmountFor(current, month); refunded > alloc {
856					return fmt.Errorf("收款 %q 在 %s 的累计退款 %d 分超过该月分配 %d 分（累计超退），余额异常", pid, month, refunded, alloc)
857				}
858			}
859		}
860		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
861		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款按最新分配在该月
862		// 计入并扣除退款后的合计）必须满足 0 ≤ 实收 ≤ 当前应付。越界说明
863		// 金额与记录不一致。
864		for key, b := range s.Bills {
865			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
866			if err != nil {
867				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
868			}
869			received, err := paymentReceived(s, b.CustomerID, b.Month)
870			if err != nil {
871				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
872			}
873			if received > payable {
874				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
875			}
876		}
877		return nil
878	}
