880	// validatePlanRules 校验阶梯方案的标识、名称、月费与阶梯规则本身自洽：
881	// 月费为非负整数分，至少一档，有限上限为严格递增的正整数，最后一档无
882	// 上限，单价非负。
883	func validatePlanRules(p *plan) error {
884		if p.ID == "" || p.Name == "" {
885			return fmt.Errorf("方案 %q 的标识或名称为空", p.ID)
886		}
887		if p.MonthlyFee < 0 {
888			return fmt.Errorf("方案 %q 的月费为负", p.ID)
889		}
890		if len(p.Tiers) == 0 {
891			return fmt.Errorf("方案 %q 至少需要一档阶梯", p.ID)
892		}
893		prev := int64(0)
894		for i, t := range p.Tiers {
895			if t.Price < 0 {
896				return fmt.Errorf("方案 %q 第 %d 档单价为负", p.ID, i+1)
897			}
898			if i == len(p.Tiers)-1 {
899				if t.Limit != 0 {
900					return fmt.Errorf("方案 %q 最后一档必须无上限", p.ID)
901				}
902			} else {
903				if t.Limit <= 0 {
904					return fmt.Errorf("方案 %q 第 %d 档上限必须是正整数", p.ID, i+1)
905				}
906				if t.Limit <= prev {
907					return fmt.Errorf("方案 %q 的有限上限必须严格递增", p.ID)
908				}
909				prev = t.Limit
910			}
911		}
912		return nil
913	}
