915	// tiersEqual 判定两份阶梯规则完全相同。
916	func tiersEqual(a, b []tier) bool {
917		if len(a) != len(b) {
918			return false
919		}
920		for i := range a {
921			if a[i] != b[i] {
922				return false
923			}
924		}
925		return true
926	}
927	
928	// segmentsEqual 判定两份分段列表完全相同。
929	func segmentsEqual(a, b []lineSegment) bool {
930		if len(a) != len(b) {
931			return false
932		}
933		for i := range a {
934			if a[i] != b[i] {
935				return false
936			}
937		}
938		return true
939	}
940	
941	// sortedByInstant 判定用量记录是否按（解析后的时间点升序、同一时间按
942	// 标识字典序）排列，即阶梯计价的计价顺序。
943	func sortedByInstant(recs []*usageRecord) bool {
944		for i := 1; i < len(recs); i++ {
945			ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
946			tj, _ := time.Parse(time.RFC3339, recs[i].Time)
947			ui, uj := ti.UTC(), tj.UTC()
948			if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
949				return false
950			}
951		}
952		return true
953	}
954	
955	// validateTieredBill 校验阶梯账单：方案引用有效、快照与方案一致、账单方案
956	// 符合账期月的方案安排，并按保存的方案规则从零累计重放计价，逐条比对分段、
957	// 小计、各档合计与总金额；任何不符都视为数据损坏。
958	func (s *state) validateTieredBill(key string, b *bill, c *customer) error {
959		if b.PlanID == "" {
960			return fmt.Errorf("账单 %q 缺少方案标识", key)
961		}
962		p, ok := s.Plans[b.PlanID]
963		if !ok {
964			return fmt.Errorf("账单 %q 引用了不存在的方案 %q", key, b.PlanID)
965		}
966		if b.PlanName != p.Name {
967			return fmt.Errorf("账单 %q 的方案名称快照与方案 %q 不符", key, b.PlanID)
968		}
969		if !tiersEqual(b.PlanTiers, p.Tiers) {
970			return fmt.Errorf("账单 %q 的方案规则快照与方案 %q 不符", key, b.PlanID)
971		}
972		if b.MonthlyFee != p.MonthlyFee {
973			return fmt.Errorf("账单 %q 的月费快照与方案 %q 不符", key, b.PlanID)
974		}
975		// 账单方案必须符合账期安排：创建时绑定的初始方案被生效月不晚于
976		// 账期月的最后一次变更替换（无变更时即初始绑定，兼容旧存档）。
977		if want := s.effectivePlanID(c, b.Month); want != b.PlanID {
978			return fmt.Errorf("账单 %q 的方案 %q 与账期 %s 安排的方案 %q 不一致", key, b.PlanID, b.Month, want)
979		}
980		if b.UnitPrice != 0 {
981			return fmt.Errorf("账单 %q 是阶梯账单但保存了统一单价", key)
982		}
983		if len(b.TierTotals) != len(p.Tiers) {
984			return fmt.Errorf("账单 %q 的分档合计档数与方案规则不符", key)
985		}
986		// 明细必须按计价顺序排列（前面已逐条核验与用量记录一致）。
987		recs := make([]*usageRecord, len(b.Lines))
988		for i, ln := range b.Lines {
989			recs[i] = s.Usage[ln.UsageID]
990		}
991		if !sortedByInstant(recs) {
992			return fmt.Errorf("账单 %q 的明细未按计价顺序（时间点升序、同一时间按标识字典序）排列", key)
993		}
994		priced, err := tieredPrice(p.Tiers, recs)
995		if err != nil {
996			return fmt.Errorf("账单 %q 按方案规则计价失败: %w", key, err)
997		}
998		for i, ln := range b.Lines {
999			if !segmentsEqual(ln.Segments, priced.lines[i].segments) {
1000				return fmt.Errorf("账单 %q 的明细 %q 分段与计价规则不符", key, ln.UsageID)
1001			}
1002			if ln.LineFee != priced.lines[i].fee {
1003				return fmt.Errorf("账单 %q 的明细 %q 小计与计价规则不符", key, ln.UsageID)
1004			}
1005		}
1006		for i, tt := range b.TierTotals {
1007			if tt.Quantity != priced.tierQty[i] || tt.Fee != priced.tierFee[i] {
1008				return fmt.Errorf("账单 %q 的第 %d 档合计与计价规则不符", key, i+1)
1009			}
1010		}
1011		// 原总金额 = 月费 + 全月用量费；月费不进入分档合计与逐条小计。
1012		wantTotal, err := add64(priced.totalFee, b.MonthlyFee)
1013		if err != nil || wantTotal != b.TotalFee {
1014			return fmt.Errorf("账单 %q 总金额不等于月费加全月用量费", key)
1015		}
1016		return nil
1017	}
1018	
1019	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
1020	// 只有完整保存成功后调用方才会向用户报告成功。
1021	func (s *state) save() error {
1022		if err := s.validate(); err != nil {
1023			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
1024		}
1025		data, err := json.MarshalIndent(s, "", "  ")
1026		if err != nil {
1027			return fmt.Errorf("序列化数据失败: %w", err)
1028		}
1029		data = append(data, '\n')
1030	
1031		tmp := s.path + ".tmp"
1032		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
1033		if err != nil {
1034			return fmt.Errorf("写入临时数据文件失败: %w", err)
1035		}
1036		if _, err := f.Write(data); err != nil {
1037			f.Close()
1038			os.Remove(tmp)
1039			return fmt.Errorf("写入临时数据文件失败: %w", err)
1040		}
1041		if err := f.Sync(); err != nil {
1042			f.Close()
1043			os.Remove(tmp)
1044			return fmt.Errorf("同步数据文件失败: %w", err)
1045		}
1046		if err := f.Close(); err != nil {
1047			os.Remove(tmp)
1048			return fmt.Errorf("关闭数据文件失败: %w", err)
1049		}
1050		if err := os.Rename(tmp, s.path); err != nil {
1051			os.Remove(tmp)
1052			return fmt.Errorf("替换数据文件失败: %w", err)
1053		}
1054		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
1055			dir.Sync()
1056			dir.Close()
1057		}
1058		return nil
1059	}
1060	
1061	func billKey(customerID, month string) string {
1062		return customerID + "|" + month
1063	}
1064	
1065	func planChangeKey(customerID, month string) string {
1066		return customerID + "|" + month
1067	}
1068	
1069	func suspensionKey(customerID, startMonth string) string {
1070		return customerID + "|" + startMonth
1071	}
1072	
1073	// monthInRange 判定月份 m 是否落在左闭右开区间 [start, end) 内。
1074	// 月份均为已校验的 YYYY-MM，字典序即时间序。
1075	func monthInRange(m, start, end string) bool {
1076		return m >= start && m < end
1077	}
1078	
1079	// suspensionsFor 返回某客户的全部暂停区间，按起月升序。
1080	func (s *state) suspensionsFor(customerID string) []*suspension {
1081		var list []*suspension
1082		for _, su := range s.Suspensions {
1083			if su.CustomerID == customerID {
1084				list = append(list, su)
1085			}
1086		}
1087		sort.Slice(list, func(i, j int) bool { return list[i].StartMonth < list[j].StartMonth })
1088		return list
1089	}
1090	
1091	// isSuspendedMonth 报告某客户的指定 UTC 自然月是否处于任一暂停区间内
1092	// （区间包含起月、不包含结束月；相接区间视为连续暂停）。
1093	func (s *state) isSuspendedMonth(customerID, month string) bool {
1094		for _, su := range s.Suspensions {
1095			if su.CustomerID == customerID && monthInRange(month, su.StartMonth, su.EndMonth) {
1096				return true
1097			}
1098		}
1099		return false
1100	}
1101	
1102	// planChangesFor 返回某客户的全部方案变更，按生效月升序。
1103	func (s *state) planChangesFor(customerID string) []*planChange {
1104		var list []*planChange
1105		for _, ch := range s.PlanChanges {
1106			if ch.CustomerID == customerID {
1107				list = append(list, ch)
1108			}
1109		}
1110		sort.Slice(list, func(i, j int) bool { return list[i].Month < list[j].Month })
1111		return list
1112	}
1113	
1114	// effectivePlanID 返回客户在某 UTC 自然月实际适用的阶梯方案标识：
1115	// 创建时绑定的初始方案，被生效月不晚于该月的最后一次变更替换。
1116	func (s *state) effectivePlanID(cust *customer, month string) string {
1117		planID := cust.PlanID
1118		latest := ""
1119		for _, ch := range s.PlanChanges {
1120			if ch.CustomerID == cust.ID && ch.Month <= month && ch.Month >= latest {
1121				latest = ch.Month
1122				planID = ch.PlanID
1123			}
1124		}
1125		return planID
1126	}
1127	
1128	// sealed 报告某客户的指定月份是否已封账。
1129	func (s *state) sealed(customerID, month string) bool {
1130		_, ok := s.Bills[billKey(customerID, month)]
1131		return ok
1132	}
1133	
1134	// isWithdrawn 报告指定用量标识是否已撤回。已撤回用量不参与结算、方案变更
1135	// 预检与暂停区间冲突检查，但原记录永久保留并继续参与导入判重。
1136	func (s *state) isWithdrawn(usageID string) bool {
1137		_, ok := s.Withdrawals[usageID]
1138		return ok
1139	}
1140	
1141	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
1142	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
1143		var list []*adjustment
1144		for _, a := range s.Adjustments {
1145			if a.CustomerID == customerID && a.Month == month {
1146				list = append(list, a)
1147			}
1148		}
1149		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1150		return list
1151	}
1152	
1153	// correctionsFor 返回某收款的全部分配更正，按操作序号升序。
1154	func correctionsFor(s *state, paymentID string) []*correction {
1155		var list []*correction
1156		for _, c := range s.Corrections {
1157			if c.PaymentID == paymentID {
1158				list = append(list, c)
1159			}
1160		}
1161		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1162		return list
1163	}
1164	
1165	// currentAllocations 返回一笔收款当前生效的分配：无更正时为首次登记的
1166	// 原始分配，否则为序号最大（最新）的更正的分配。
1167	func currentAllocations(s *state, p *payment) []paymentAllocation {
1168		var latest *correction
1169		for _, c := range s.Corrections {
1170			if c.PaymentID == p.ID && (latest == nil || c.Seq > latest.Seq) {
1171				latest = c
1172			}
1173		}
1174		if latest != nil {
1175			return latest.Allocations
1176		}
1177		return p.Allocations
1178	}
1179	
1180	// allocAmountFor 返回分配列表中指定月份的金额；无该月分配时为 0。
1181	func allocAmountFor(allocs []paymentAllocation, month string) int64 {
1182		for _, al := range allocs {
1183			if al.Month == month {
1184				return al.Amount
1185			}
1186		}
1187		return 0
1188	}
1189	
1190	// paymentsEverFor 返回历史上曾涉及某客户某月账单的全部收款（首次登记
1191	// 分配或任一次更正的新分配涉及该月，即使后来被更正移出），按操作序号升序。
1192	func paymentsEverFor(s *state, customerID, month string) []*payment {
1193		var list []*payment
1194		for _, p := range s.Payments {
1195			if p.CustomerID != customerID {
1196				continue
1197			}
1198			involved := p.amountFor(month) > 0
1199			if !involved {
1200				for _, c := range s.Corrections {
1201					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
1202						involved = true
1203						break
1204					}
1205				}
1206			}
1207			if involved {
1208				list = append(list, p)
1209			}
1210		}
1211		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1212		return list
1213	}
1214	
1215	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入并扣除退款后
1216	// 的实收之和。各笔净额（分配减累计退款）均为非负整数，用非负 64 位加法
1217	// 累加，溢出时返回错误。
1218	func paymentReceived(s *state, customerID, month string) (int64, error) {
1219		var received int64
1220		for _, p := range s.Payments {
1221			if p.CustomerID != customerID || p.Revoked {
1222				continue
1223			}
1224			amt := allocAmountFor(currentAllocations(s, p), month) - refundedForMonth(s, p.ID, month)
1225			if amt <= 0 {
1226				continue
1227			}
1228			var err error
1229			received, err = add64(received, amt)
1230			if err != nil {
1231				return 0, err
1232			}
1233		}
1234		return received, nil
1235	}
1236	
1237	// refundsFor 返回某收款的全部退款，按操作序号升序。
1238	func refundsFor(s *state, paymentID string) []*refund {
1239		var list []*refund
1240		for _, r := range s.Refunds {
1241			if r.PaymentID == paymentID {
1242				list = append(list, r)
1243			}
1244		}
1245		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
1246		return list
1247	}
1248	
1249	// refundedForMonth 返回某收款在指定月份的累计退款金额（分）；无退款时为 0。
1250	// 数据在载入时已校验累计不超退，合计不超过该月分配，不会溢出。
1251	func refundedForMonth(s *state, paymentID, month string) int64 {
1252		var total int64
1253		for _, r := range s.Refunds {
1254			if r.PaymentID == paymentID {
1255				total += allocAmountFor(r.Allocations, month)
1256			}
1257		}
1258		return total
1259	}
1260	
1261	// paymentHasRefunds 报告某收款是否已发生退款。首次退款后该收款的最新分配
1262	// 固定，不得再新增分配更正或整笔撤销。
1263	func paymentHasRefunds(s *state, paymentID string) bool {
1264		for _, r := range s.Refunds {
1265			if r.PaymentID == paymentID {
1266				return true
1267			}
1268		}
1269		return false
1270	}
1271	
1272	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
1273	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
1274	
1275	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
1276	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
1277	// [0, 有符号 64 位最大值] 内，全程整数运算。
1278	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
1279		var amounts []int64
1280		for _, a := range adjs {
1281			if !a.Revoked {
1282				amounts = append(amounts, a.Amount)
1283			}
1284		}
1285		net, err = sumSigned64(amounts...)
1286		if err != nil {
1287			return 0, 0, err
1288		}
1289		payable, err = addSigned64(b.TotalFee, net)
1290		if err != nil {
1291			return 0, 0, err
1292		}
1293		if payable < 0 {
1294			return 0, 0, errPayableOutOfRange
1295		}
1296		return net, payable, nil
1297	}
1298

