220		}
221		price, err := parsePrice(priceText)
222		if err != nil {
223			return err
224		}
225	
226		s, err := loadStore(dir)
227		if err != nil {
228			return err
229		}
230		if _, exists := s.Customers[id]; exists {
231			return fmt.Errorf("客户标识 %q 已存在，客户单价创建后不可修改", id)
232		}
233		s.Customers[id] = &customer{ID: id, Name: name, Price: price}
234		if err := s.save(); err != nil {
235			return err
236		}
237		fmt.Fprintf(stdout, "已登记客户 %q（%s），固定单价 %d 分（%s）\n", id, name, price, moneyFen(price))
238		return nil
239	}
240	
241	func parsePrice(text string) (int64, error) {
242		text = strings.TrimSpace(text)
243		price, err := strconv.ParseInt(text, 10, 64)
244		if err != nil {
245			return 0, fmt.Errorf("单价 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
246		}
247		if price < 0 {
248			return 0, fmt.Errorf("单价必须是非负整数分，收到 %d", price)
249		}
250		return price, nil
251	}
