253	// parsedRow 是导入文件中一行解析后的候选用量。
254	type parsedRow struct {
255		line int // 文件中的行号（含表头），用于报错定位
256		rec  usageRecord
257		t    time.Time
258	}
259	
260	func cmdUsageImport(dir, file string) error {
261		var reader io.ReadCloser
262		var source string
263		if file == "-" {
264			reader = io.NopCloser(os.Stdin)
265			source = "标准输入"
266		} else {
267			f, err := os.Open(file)
268			if err != nil {
269				return fmt.Errorf("无法打开用量文件 %s: %w", file, err)
270			}
271			reader = f
272			source = file
273		}
274		defer reader.Close()
275	
276		rows, parseErrs := parseUsageFile(reader)
277	
278		s, err := loadStore(dir)
279		if err != nil {
280			return err
281		}
282	
283		// 先校验：任何问题都在此阶段收集，全部通过后才一次性修改并保存，
284		// 保证“整批导入先校验再生效”，失败不留下任何新用量。
285		var problems []string
286		problems = append(problems, parseErrs...)
287	
288		accepted := make(map[string]*parsedRow) // 本批内首次出现、内容确定的记录
289		var ordered []*parsedRow
290		newCount, dupCount := 0, 0
291	
292		for _, r := range rows {
293			cust, ok := s.Customers[r.rec.CustomerID]
294			if !ok {
295				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识 %q 不存在", r.line, r.rec.CustomerID))
296				continue
297			}
298	
299			// 去重判定同时对“库中已有”和“本文件内已出现”生效，且先于暂停、
300			// 封账与金额预检：已存在记录（含已撤回记录）按客户、解析后的时间点
301			// 和数量与原内容判重，相同重放计入重复跳过——即使该月后来已封账、
302			// 暂停或后续方案计价会溢出也不受阻；已撤回记录的重放不会恢复记录。
303			var existing *usageRecord
304			if inStore, ok := s.Usage[r.rec.ID]; ok {
305				existing = inStore
306			} else if inBatch, ok := accepted[r.rec.ID]; ok {
307				existing = &inBatch.rec
308			}
309			if existing != nil {
310				if !sameUsage(existing, &r.rec, r.t) {
311					problems = append(problems, fmt.Sprintf("第 %d 行：用量标识 %q 已存在但内容不同（已有客户=%s 时间=%s 数量=%d）",
312						r.line, r.rec.ID, existing.CustomerID, existing.Time, existing.Quantity))
313					continue
314				}
315				dupCount++
316				continue
317			}
318	
319			// 以下为全新用量：暂停、封账及当前方案下金额预检只约束全新用量。
320			// 暂停月的新用量一律拒绝：按记录时间换算的 UTC 月份判断，处于任一
321			// 暂停区间（含起月、不含结束月）即整批失败并指出行号。
322			rowMonth := r.t.UTC().Format("2006-01")
323			if s.isSuspendedMonth(r.rec.CustomerID, rowMonth) {
324				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 处于暂停区间，暂停服务期间不接收用量（新用量 %q 被拒绝）",
325					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
326				continue
327			}
328			// 金额可行性预检：固定单价客户检查 数量×单价；阶梯客户按记录时间
329			// 换算的 UTC 月份的有效方案，以单条数量从零计价，检查分段金额不
330			// 溢出（金额单位：分）。
331			if cust.PlanID == "" {
332				if _, err := mul64(r.rec.Quantity, cust.Price); err != nil {
333					problems = append(problems, fmt.Sprintf("第 %d 行：数量 %d × 单价 %d 金额溢出有符号 64 位整数范围", r.line, r.rec.Quantity, cust.Price))
334					continue
335				}
336			} else {
337				rec := r.rec
338				planID := s.effectivePlanID(cust, rowMonth)
339				if _, err := tieredPrice(s.Plans[planID].Tiers, []*usageRecord{&rec}); err != nil {
340					problems = append(problems, fmt.Sprintf("第 %d 行：按 %s 月有效方案 %q 对单条数量从零计价失败：%v", r.line, rowMonth, planID, err))
341					continue
342				}
343			}
344	
345			// 全新标识：不得进入该客户已封账的 UTC 自然月。
346			if s.sealed(r.rec.CustomerID, rowMonth) {
347				problems = append(problems, fmt.Sprintf("第 %d 行：客户 %s 的 %s 已封账，新用量 %q 不得进入",
348					r.line, r.rec.CustomerID, rowMonth, r.rec.ID))
349				continue
350			}
351	
352			rr := r
353			accepted[r.rec.ID] = rr
354			ordered = append(ordered, rr)
355			newCount++
356		}
357	
358		if len(problems) > 0 {
359			return fmt.Errorf("导入失败，整批未生效（共 %d 个问题）：\n  %s", len(problems), strings.Join(problems, "\n  "))
360		}
361	
362		for _, r := range ordered {
363			rec := r.rec
364			s.Usage[rec.ID] = &rec
365		}
366		if err := s.save(); err != nil {
367			return err
368		}
369		fmt.Fprintf(stdout, "导入完成（%s）：新增 %d 条，重复跳过 %d 条\n", source, newCount, dupCount)
370		return nil
371	}
372	
373	// parseUsageFile 完整读取 CSV，做格式层面的解析；业务层面的校验在调用方完成。
374	func parseUsageFile(r io.Reader) ([]*parsedRow, []string) {
375		cr := csv.NewReader(r)
376		cr.FieldsPerRecord = 4
377		cr.TrimLeadingSpace = true
378	
379		header, err := cr.Read()
380		if err == io.EOF {
381			return nil, []string{"文件为空：首行必须是表头 " + usageHeader}
382		}
383		if err != nil {
384			return nil, []string{fmt.Sprintf("无法读取表头：%v（首行必须是 %s）", err, usageHeader)}
385		}
386		for i := range header {
387			header[i] = strings.TrimSpace(header[i])
388		}
389		if len(header) != 4 || header[0] != "usage_id" || header[1] != "customer_id" ||
390			header[2] != "time" || header[3] != "quantity" {
391			return nil, []string{fmt.Sprintf("表头必须是 %s，实际为 %s", usageHeader, strings.Join(header, ","))}
392		}
393	
394		var rows []*parsedRow
395		var problems []string
396		line := 1
397		for {
398			rec, err := cr.Read()
399			if err == io.EOF {
400				break
401			}
402			line++
403			if err != nil {
404				problems = append(problems, fmt.Sprintf("第 %d 行：CSV 格式错误：%v", line, err))
405				if pe, ok := err.(*csv.ParseError); ok && pe.Err == csv.ErrFieldCount {
406					// 字段数错误后继续读取仍可能拿到错乱记录，直接终止解析。
407					break
408				}
409				continue
410			}
411			for i := range rec {
412				rec[i] = strings.TrimSpace(rec[i])
413			}
414	
415			id, custID, ts, qtyText := rec[0], rec[1], rec[2], rec[3]
416			if id == "" {
417				problems = append(problems, fmt.Sprintf("第 %d 行：用量标识不能为空", line))
418				continue
419			}
420			if custID == "" {
421				problems = append(problems, fmt.Sprintf("第 %d 行：客户标识不能为空", line))
422				continue
423			}
424			t, err := time.Parse(time.RFC3339, ts)
425			if err != nil {
426				problems = append(problems, fmt.Sprintf("第 %d 行：时间 %q 不是 RFC3339 格式：%v", line, ts, err))
427				continue
428			}
429			qty, err := strconv.ParseInt(qtyText, 10, 64)
430			if err != nil {
431				problems = append(problems, fmt.Sprintf("第 %d 行：数量 %q 不是有符号 64 位整数", line, qtyText))
432				continue
433			}
434			if qty <= 0 {
435				problems = append(problems, fmt.Sprintf("第 %d 行：数量必须是正整数，收到 %d", line, qty))
436				continue
437			}
438	
439			rows = append(rows, &parsedRow{
440				line: line,
441				rec:  usageRecord{ID: id, CustomerID: custID, Time: ts, Quantity: qty},
442				t:    t,
443			})
444		}
445		return rows, problems
446	}
447	
448	// sameUsage 按（客户、解析后的时间点、数量）判定两条记录内容是否相同，
449	// 时间比较的是瞬间，因此 Z 与 +08:00 表示同一时刻视为相同。
450	func sameUsage(existing *usageRecord, candidate *usageRecord, candidateT time.Time) bool {
451		if existing.CustomerID != candidate.CustomerID || existing.Quantity != candidate.Quantity {
452			return false
453		}
454		et, err := time.Parse(time.RFC3339, existing.Time)
455		if err != nil {
456			return existing.Time == candidate.Time
457		}
458		return et.Equal(candidateT)
459	}
460	
461	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
462	func validMonth(m string) bool {
463		t, err := time.Parse("2006-01", m)
464		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
465			return false
466		}
467		return true
468	}
469	
470	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
471	func inMonth(rfc3339, month string) bool {
472		t, err := time.Parse(time.RFC3339, rfc3339)
473		if err != nil {
474			return false
475		}
476		return t.UTC().Format("2006-01") == month
477	}
478	
479	// utcMonth 返回 RFC3339 时间换算 UTC 后的自然月（YYYY-MM）。
480	// 入参时间均已在载入/导入时校验为 RFC3339。
481	func utcMonth(rfc3339 string) string {
482		t, _ := time.Parse(time.RFC3339, rfc3339)
483		return t.UTC().Format("2006-01")
484	}
485	
486	func cmdBillSettle(dir, customerID, month string) error {
487		if !validMonth(month) {
488			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
489		}
490		s, err := loadStore(dir)
491		if err != nil {
492			return err
493		}
494		cust, ok := s.Customers[customerID]
495		if !ok {
496			return fmt.Errorf("客户标识 %q 不存在", customerID)
497		}
498	
499		// 暂停月无论方案月费多少都拒绝结算：不封账、不生成零金额账单。
500		if s.isSuspendedMonth(customerID, month) {
501			return fmt.Errorf("客户 %s 的 %s 处于暂停区间，暂停服务期间不产生月费账单，拒绝结算且不封账", customerID, month)
502		}
503	
504		key := billKey(customerID, month)
505		if existing, ok := s.Bills[key]; ok {
506			// 幂等：同一客户同一月份重复结算，直接返回原账单，
507			// 不重新计费、不产生新账单或调整、不落盘。
508			fmt.Fprintf(stdout, "客户 %s 的 %s 已结算，返回原账单（幂等，不重新计费）：\n\n", customerID, month)
509			printBill(existing, cust, s)
510			return nil
511		}
512	
513		// 归集该客户 UTC 自然月内的全部有效（未撤回）用量，区间为左闭右开
514		// [月初, 下月初)。有效方案月费大于 0 的阶梯客户即使无用量也须出账
515		// （收取一次整月月费）；月费为 0 的方案与固定单价客户无用量时仍拒绝
516		// 结算且不封账。
517		inMonthRecs := monthUsage(s, customerID, month)
518		if len(inMonthRecs) == 0 && !monthlyFeeBillable(s, cust, month) {
519			return fmt.Errorf("客户 %s 在 %s 没有用量，拒绝结算且不封账", customerID, month)
520		}
521	
522		// 绑定阶梯方案的客户走按月累计分档计价；固定单价客户保持原路径。
523		if cust.PlanID != "" {
524			return settleTiered(s, cust, month, inMonthRecs)
525		}
526	
527		b, err := buildFixedBill(cust, month, inMonthRecs)
528		if err != nil {
529			return fmt.Errorf("%v，拒绝结算且不封账", err)
530		}
531		s.Bills[key] = b
532	
533		// 账单与封账状态在同一次原子保存中一起持久化；保存失败则一切不生效。
534		if err := s.save(); err != nil {
535			delete(s.Bills, key)
536			return err
537		}
538		fmt.Fprintf(stdout, "结算完成，客户 %s 的 %s 已封账：\n\n", customerID, month)
539		printBill(b, cust, s)
540		return nil
541	}
