563	// monthUsage 归集客户在某 UTC 自然月（左闭右开 [月初, 下月初)）内的全部
564	// 有效（未撤回）用量，并按计价顺序（解析后的时间点升序、同一时间按标识
565	// 字典序）排列。已撤回用量不计费用，不参与单笔及批量结算；阶梯计价将剩余
566	// 记录按原有时间点及标识顺序从零累计重新分档。
567	func monthUsage(s *state, customerID, month string) []*usageRecord {
568		var recs []*usageRecord
569		for _, u := range s.Usage {
570			if s.isWithdrawn(u.ID) {
571				continue
572			}
573			if u.CustomerID == customerID && inMonth(u.Time, month) {
574				recs = append(recs, u)
575			}
576		}
577		sortByInstant(recs)
578		return recs
579	}
580	
581	// buildFixedBill 为固定单价客户构造账单（不落盘）：逐条 数量×单价 并汇总，
582	// 全程整数运算，任何一步溢出都返回错误。recs 须已按计价顺序排列。
583	func buildFixedBill(cust *customer, month string, recs []*usageRecord) (*bill, error) {
584		lines := make([]billLine, 0, len(recs))
585		var totalQty, totalFee int64
586		for _, u := range recs {
587			lineFee, err := mul64(u.Quantity, cust.Price)
588			if err != nil {
589				return nil, fmt.Errorf("用量 %s：数量 %d × 单价 %d 金额溢出", u.ID, u.Quantity, cust.Price)
590			}
591			if totalQty, err = add64(totalQty, u.Quantity); err != nil {
592				return nil, fmt.Errorf("汇总数量溢出有符号 64 位整数范围")
593			}
594			if totalFee, err = add64(totalFee, lineFee); err != nil {
595				return nil, fmt.Errorf("汇总金额溢出有符号 64 位整数范围")
596			}
597			lines = append(lines, billLine{
598				UsageID:  u.ID,
599				Time:     u.Time,
600				Quantity: u.Quantity,
601				LineFee:  lineFee,
602			})
603		}
604		return &bill{
605			ID:         stableBillID(cust.ID, month),
606			CustomerID: cust.ID,
607			Month:      month,
608			TotalQty:   totalQty,
609			UnitPrice:  cust.Price,
610			TotalFee:   totalFee,
611			Lines:      lines,
612			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
613		}, nil
614	}
615	
616	func sortByInstant(us []*usageRecord) {
617		// 入参时间均已在载入/导入时校验为 RFC3339。
618		sort.Slice(us, func(i, j int) bool {
619			ti, _ := time.Parse(time.RFC3339, us[i].Time)
620			tj, _ := time.Parse(time.RFC3339, us[j].Time)
621			ui, uj := ti.UTC(), tj.UTC()
622			if !ui.Equal(uj) {
623				return ui.Before(uj)
624			}
625			return us[i].ID < us[j].ID
626		})
627	}
628	
629	// stableBillID 由（客户标识，月份）确定性派生：跨进程稳定，且客户/月份间唯一。
630	func stableBillID(customerID, month string) string {
631		sum := sha256.Sum256([]byte(customerID + "\x00" + month))
632		return "BILL-" + hex.EncodeToString(sum[:])[:16]
633	}
634	
635	func printBill(b *bill, cust *customer, s *state) {
636		adjs := adjustmentsFor(s, b.CustomerID, b.Month)
637		// 收款历史保留所有曾涉及本账单的收款：首次登记或任一次更正分配
638		// 涉及该月即纳入，即使后来被更正移出。
639		pays := paymentsEverFor(s, b.CustomerID, b.Month)
640		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
641		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
642		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
643		tiered := b.Pricing == "tiered"
644		if tiered {
645			// 阶梯账单明确计价类型并展示方案与完整规则，不伪造统一单价。
646			fmt.Fprintf(stdout, "计价类型：阶梯计费（按 UTC 自然月累计用量分档计价，每月从零累计）\n")
647			fmt.Fprintf(stdout, "方案：%s（%s）\n", b.PlanID, b.PlanName)
648			fmt.Fprintln(stdout, "阶梯规则：")
649			for i, t := range b.PlanTiers {
650				if t.Limit == 0 {
651					fmt.Fprintf(stdout, "  第 %d 档：累计数量无上限，单价 %d 分（%s）\n", i+1, t.Price, moneyFen(t.Price))
652				} else {
653					fmt.Fprintf(stdout, "  第 %d 档：累计上限 %d，单价 %d 分（%s）\n", i+1, t.Limit, t.Price, moneyFen(t.Price))
654				}
655			}
656		} else {
657			fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
658		}
659		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
660		if tiered {
661			// 阶梯账单分列月费与用量费：原总金额 = 月费 + 全月用量费；
662			// 月费不计入总数量、各档金额或逐条小计。
663			usageFee := b.TotalFee - b.MonthlyFee
664			fmt.Fprintf(stdout, "月费：%d 分（%s，整月收取，不按天折算）\n", b.MonthlyFee, moneyFen(b.MonthlyFee))
665			fmt.Fprintf(stdout, "用量费：%d 分（%s）\n", usageFee, moneyFen(usageFee))
666			fmt.Fprintf(stdout, "原总金额：%d 分（%s，月费加全月用量费）\n", b.TotalFee, moneyFen(b.TotalFee))
667		} else {
668			fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
669		}
670		if tiered {
671			fmt.Fprintln(stdout, "各档合计：")
672			for i, tt := range b.TierTotals {
673				fmt.Fprintf(stdout, "  第 %d 档：数量 %d，单价 %d 分，金额 %d 分（%s）\n",
674					i+1, tt.Quantity, b.PlanTiers[i].Price, tt.Fee, moneyFen(tt.Fee))
675			}
