677		// 数据在载入时已校验一致，此处计算不会出错。
678		net, payable, _ := billTotals(b, adjs)
679		received, _ := paymentReceived(s, b.CustomerID, b.Month)
680		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
681		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
682		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
683		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
684		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
685		if len(b.Lines) == 0 {
686			fmt.Fprintln(stdout, "明细：无（本账期无用量，仅收取月费）")
687		} else {
688			fmt.Fprintln(stdout, "明细：")
689		}
690		for i, ln := range b.Lines {
691			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
692				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
693			// 阶梯账单逐条展示跨档分段的数量、单价与小计。
694			for j, seg := range ln.Segments {
695				fmt.Fprintf(stdout, "     分段 %d：第 %d 档 数量=%d 单价=%d 分 小计=%d 分（%s）\n",
696					j+1, seg.Tier+1, seg.Quantity, b.PlanTiers[seg.Tier].Price, seg.Fee, moneyFen(seg.Fee))
697			}
698		}
699		if len(adjs) == 0 {
700			fmt.Fprintln(stdout, "调整与撤销历史：无")
701		} else {
702			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
703			for i, ev := range historyEvents(adjs) {
704				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
705			}
706		}
707		if len(pays) == 0 {
708			fmt.Fprintln(stdout, "收款与撤销历史：无")
709		} else {
710			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
711			for i, ev := range paymentHistoryEvents(s, pays, b.Month) {
712				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
713			}
714		}
715	}
