717	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
718	func historyEvents(adjs []*adjustment) []string {
719		type event struct {
720			seq  int64
721			text string
722		}
723		var events []event
724		for _, a := range adjs {
725			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
726				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
727			if a.Revoked {
728				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
729					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
730			}
731		}
732		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
733		out := make([]string, len(events))
734		for i, ev := range events {
735			out[i] = ev.text
736		}
737		return out
738	}
