754	// paymentHistoryEvents 把收款登记、分配更正与撤销展开为按操作序号排序的
755	// 可读历史条目；month 为当前展示账单所在月份。收款事件展示首次登记时在
756	// 本账单的分配，更正事件展示本账单分配的前后变化，撤销事件展示被整笔取消
757	// 的最新分配。
758	func paymentHistoryEvents(s *state, pays []*payment, month string) []string {
759		type event struct {
760			seq  int64
761			text string
762		}
763		var events []event
764		for _, p := range pays {
765			alloc := p.amountFor(month)
766			events = append(events, event{p.Seq, fmt.Sprintf("收款 %s：总额 %d 分（%s），本账单分配 %d 分（%s），备注：%s，当前状态：%s（客户 %s）",
767				p.ID, p.Total, moneyFen(p.Total), alloc, moneyFen(alloc), p.Note, paymentStatus(p), p.CustomerID)})
768			// 以首次登记分配为起点，按序号回放该收款在本账单的分配变化。
769			running := alloc
770			for _, c := range correctionsFor(s, p.ID) {
771				after := allocAmountFor(c.Allocations, month)
772				if running == 0 && after == 0 {
773					continue // 本次更正不涉及本账单
774				}
775				events = append(events, event{c.Seq, fmt.Sprintf("更正 %s：原因：%s（关联收款 %s，本账单分配 %d 分 → %d 分）",
776					c.ID, c.Reason, p.ID, running, after)})
777				running = after
778			}
779			if p.Revoked {
780				// 整笔撤销取消的是撤销时的最新分配。
781				events = append(events, event{p.RevokeSeq, fmt.Sprintf("撤销收款 %s：原因：%s（关联收款 %s，总额 %d 分，本账单分配 %d 分）",
782					p.ID, p.RevokeReason, p.ID, p.Total, running)})
783			}
784			// 退款在其发生序号减少本账单实收；退款不可撤销，记录永久保留。
785			for _, r := range refundsFor(s, p.ID) {
786				amt := allocAmountFor(r.Allocations, month)
787				if amt <= 0 {
788					continue // 本次退款不涉及本账单
789				}
790				events = append(events, event{r.Seq, fmt.Sprintf("退款 %s：原因：%s（关联收款 %s，本账单退款 %d 分（%s））",
791					r.ID, r.Reason, p.ID, amt, moneyFen(amt))})
792			}
793		}
794		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
795		out := make([]string, len(events))
796		for i, ev := range events {
797			out[i] = ev.text
798		}
799		return out
800	}
