809	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
810	func parseAmount(text string) (int64, error) {
811		text = strings.TrimSpace(text)
812		amount, err := strconv.ParseInt(text, 10, 64)
813		if err != nil {
814			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
815		}
816		if amount == 0 {
817			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
818		}
819		return amount, nil
820	}
