822	func cmdBillAdjust(dir, customerID, month, adjID, amountText, reason string) error {
823		if !validMonth(month) {
824			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
825		}
826		if strings.TrimSpace(adjID) == "" {
827			return fmt.Errorf("调整标识不能为空")
828		}
829		amount, err := parseAmount(amountText)
830		if err != nil {
831			return err
832		}
833		if strings.TrimSpace(reason) == "" {
834			return fmt.Errorf("调整原因不能为空")
835		}
836	
837		s, err := loadStore(dir)
838		if err != nil {
839			return err
840		}
841		if _, ok := s.Customers[customerID]; !ok {
842			return fmt.Errorf("客户标识 %q 不存在", customerID)
843		}
844		b, ok := s.Bills[billKey(customerID, month)]
845		if !ok {
846			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），费用调整只能作用于已存在账单", customerID, month)
847		}
848	
849		if existing, ok := s.Adjustments[adjID]; ok {
850			// 相同标识按客户、月份、金额、原因判断重复：内容相同返回已保存
851			// 记录，不再次增减应付；已撤销的重放仍返回已撤销状态，不重新生效。
852			if existing.CustomerID == customerID && existing.Month == month &&
853				existing.Amount == amount && existing.Reason == reason {
854				fmt.Fprintf(stdout, "调整 %q 已存在且内容相同，返回已保存记录（不重复增减应付）：\n\n", adjID)
855				printAdjustment(existing, s)
856				return nil
857			}
858			return fmt.Errorf("调整标识 %q 已存在但内容不同（已有：客户=%s 月份=%s 金额=%d 原因=%q），拒绝复用",
859				adjID, existing.CustomerID, existing.Month, existing.Amount, existing.Reason)
860		}
861	
862		// 应付可行性预检：原总金额 + 全部未撤销调整 + 本次金额必须落在
863		// [0, 有符号 64 位最大值] 内，且不得低于已登记实收，否则拒绝且
864		// 不占用该调整标识。
865		_, payable, err := billTotals(b, adjustmentsFor(s, customerID, month))
866		if err != nil {
867			return fmt.Errorf("账单当前应付异常，拒绝调整: %w", err)
868		}
869		received, err := paymentReceived(s, customerID, month)
870		if err != nil {
871			return fmt.Errorf("实收累计异常，拒绝调整: %w", err)
872		}
873		newPayable, err := addSigned64(payable, amount)
874		if err != nil {
875			return fmt.Errorf("调整后当前应付超出有符号 64 位最大值（当前 %d 分，本次 %+d 分），拒绝调整", payable, amount)
876		}
877		if newPayable < 0 {
878			return fmt.Errorf("调整后当前应付将为 %d 分（小于 0，当前 %d 分，本次 %+d 分），拒绝调整", newPayable, payable, amount)
879		}
880		if newPayable < received {
881			return fmt.Errorf("调整后当前应付 %d 分将低于实收 %d 分（当前 %d 分，本次 %+d 分），拒绝调整；可先撤销误登记的收款再重试",
882				newPayable, received, payable, amount)
883		}
884	
885		a := &adjustment{
886			ID:         adjID,
887			CustomerID: customerID,
888			Month:      month,
889			Amount:     amount,
890			Reason:     reason,
891			CreatedAt:  time.Now().UTC().Format(time.RFC3339),
892		}
893		s.NextSeq++
894		a.Seq = s.NextSeq
895		s.Adjustments[adjID] = a
896	
897		// 调整记录与序号在同一次原子保存中持久化；保存失败则一切不生效，
898		// 该调整标识不被占用。
899		if err := s.save(); err != nil {
900			delete(s.Adjustments, adjID)
901			s.NextSeq--
902			return err
903		}
904		fmt.Fprintf(stdout, "已登记%s调整 %q，客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
905			adjustKind(amount), adjID, customerID, month, newPayable, moneyFen(newPayable))
906		printAdjustment(a, s)
907		return nil
908	}
