910	func cmdBillRevoke(dir, adjID, reason string) error {
911		if strings.TrimSpace(adjID) == "" {
912			return fmt.Errorf("调整标识不能为空")
913		}
914		if strings.TrimSpace(reason) == "" {
915			return fmt.Errorf("撤销原因不能为空")
916		}
917	
918		s, err := loadStore(dir)
919		if err != nil {
920			return err
921		}
922		a, ok := s.Adjustments[adjID]
923		if !ok {
924			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
925		}
926	
927		if a.Revoked {
928			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
929			// 改用其他原因则拒绝。
930			if a.RevokeReason == reason {
931				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
932				printAdjustment(a, s)
933				return nil
934			}
935			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
936		}
937	
938		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
939		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
940		// 改变余额后重试。
941		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
942		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
943		if err != nil {
944			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
945		}
946		received, err := paymentReceived(s, a.CustomerID, a.Month)
947		if err != nil {
948			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
949		}
950		neg, err := neg64(a.Amount)
951		if err != nil {
952			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
953		}
954		newPayable, err := addSigned64(payable, neg)
955		if err != nil {
956			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
957				payable, a.Amount)
958		}
959		if newPayable < 0 {
960			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
961				newPayable, payable, a.Amount)
962		}
963		if newPayable < received {
964			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
965				newPayable, received, payable, a.Amount)
966		}
967	
968		a.Revoked = true
969		a.RevokeReason = reason
970		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
971		s.NextSeq++
972		a.RevokeSeq = s.NextSeq
973	
974		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
975		if err := s.save(); err != nil {
976			a.Revoked = false
977			a.RevokeReason = ""
978			a.RevokedAt = ""
979			a.RevokeSeq = 0
980			s.NextSeq--
981			return err
982		}
983		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
984			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
985		printAdjustment(a, s)
986		return nil
987	}
