991		b := s.Bills[billKey(a.CustomerID, a.Month)]
992		_, payable, _ := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
993		fmt.Fprintf(stdout, "调整标识：%s\n", a.ID)
