1006	// parsePositiveAmount 解析收款金额：正整数分（不接受零、负数、小数）。
1007	func parsePositiveAmount(text string) (int64, error) {
1008		text = strings.TrimSpace(text)
1009		amount, err := strconv.ParseInt(text, 10, 64)
1010		if err != nil {
1011			return 0, fmt.Errorf("收款金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
1012		}
1013		if amount <= 0 {
1014			return 0, fmt.Errorf("收款金额必须是正整数分，收到 %d", amount)
1015		}
1016		return amount, nil
1017	}
