1019	func cmdBillPay(dir, customerID, month, payID, amountText, note string) error {
1020		if !validMonth(month) {
1021			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1022		}
1023		amount, err := parsePositiveAmount(amountText)
1024		if err != nil {
1025			return err
1026		}
1027		// 单账单收款视为只有一项分配的汇款，与 bill remit 共用同一核心。
1028		return registerPayment(dir, customerID, payID, amount, note,
1029			[]paymentAllocation{{Month: month, Amount: amount}})
1030	}
1031	
1032	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
1033		total, err := parsePositiveAmount(totalText)
1034		if err != nil {
1035			return err
1036		}
1037		allocs, err := parseAllocations(allocArgs)
1038		if err != nil {
1039			return err
1040		}
1041		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
1042		var sum int64
1043		for _, al := range allocs {
1044			sum, err = add64(sum, al.Amount)
1045			if err != nil {
1046				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
1047			}
1048		}
1049		if sum != total {
1050			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
1051		}
1052		return registerPayment(dir, customerID, payID, total, note, allocs)
1053	}
1054	
1055	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
1056	// 月份不得重复，每项金额为正整数分。
1057	func parseAllocations(args []string) ([]paymentAllocation, error) {
1058		if len(args) == 0 {
1059			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
1060		}
1061		seen := make(map[string]bool)
1062		allocs := make([]paymentAllocation, 0, len(args))
1063		for _, arg := range args {
1064			parts := strings.Split(arg, ":")
1065			if len(parts) != 2 {
1066				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
1067			}
1068			month := strings.TrimSpace(parts[0])
1069			if !validMonth(month) {
1070				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
1071			}
1072			if seen[month] {
1073				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
1074			}
1075			seen[month] = true
1076			amount, err := parsePositiveAmount(parts[1])
1077			if err != nil {
1078				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
1079			}
1080			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
1081		}
1082		return allocs, nil
1083	}
1084	
1085	// registerPayment 是 bill pay 与 bill remit 共用的收款登记核心：
1086	// 先整体校验再整笔生效，任何一项不合法都不落盘、不占用收款标识。
1087	func registerPayment(dir, customerID, payID string, total int64, note string, allocs []paymentAllocation) error {
1088		if strings.TrimSpace(payID) == "" {
1089			return fmt.Errorf("收款标识不能为空")
1090		}
1091		if strings.TrimSpace(note) == "" {
1092			return fmt.Errorf("收款备注不能为空")
1093		}
1094		// 分配顺序不影响收款身份：统一按月份升序保存与比较。
1095		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1096	
1097		s, err := loadStore(dir)
1098		if err != nil {
1099			return err
1100		}
1101		if _, ok := s.Customers[customerID]; !ok {
1102			return fmt.Errorf("客户标识 %q 不存在", customerID)
1103		}
1104		for _, al := range allocs {
1105			if _, ok := s.Bills[billKey(customerID, al.Month)]; !ok {
1106				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），收款只能登记到已存在账单", customerID, al.Month)
1107			}
1108		}
1109	
1110		if existing, ok := s.Payments[payID]; ok {
1111			// 相同标识按客户、总额、备注与月份-金额对应关系判断重复：内容相同
1112			// 返回已保存记录，不再次计入实收，也不受当前余额变化影响；
1113			// 已撤销的重放仍返回已撤销状态，不恢复实收。
1114			if samePaymentContent(existing, customerID, total, note, allocs) {
1115				fmt.Fprintf(stdout, "收款 %q 已存在且内容相同，返回已保存记录（不重复计入实收）：\n\n", payID)
1116				printPayment(existing, s)
1117				return nil
1118			}
1119			return fmt.Errorf("收款标识 %q 已存在但内容不同（已有：客户=%s 总额=%d 备注=%q 分配=%s），拒绝复用",
1120				payID, existing.CustomerID, existing.Total, existing.Note, formatAllocations(existing.Allocations))
1121		}
1122	
1123		// 首次登记：每项分配不得超过对应账单的未收余额，全部合法才整笔生效。
1124		for _, al := range allocs {
1125			b := s.Bills[billKey(customerID, al.Month)]
1126			_, payable, err := billTotals(b, adjustmentsFor(s, customerID, al.Month))
1127			if err != nil {
1128				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝登记收款: %w", customerID, al.Month, err)
1129			}
1130			received, err := paymentReceived(s, customerID, al.Month)
1131			if err != nil {
1132				return fmt.Errorf("客户 %s 的 %s 实收累计溢出有符号 64 位整数范围，拒绝登记收款: %w", customerID, al.Month, err)
1133			}
1134			if payable == 0 {
1135				return fmt.Errorf("客户 %s 的 %s 当前应付为 0 分，不能登记正额收款", customerID, al.Month)
1136			}
1137			if al.Amount > payable-received {
1138				return fmt.Errorf("分配 %d 分超过未收余额 %d 分（客户 %s 的 %s：当前应付 %d 分，实收 %d 分），拒绝登记",
1139					al.Amount, payable-received, customerID, al.Month, payable, received)
1140			}
1141		}
1142	
1143		p := &payment{
1144			ID:          payID,
1145			CustomerID:  customerID,
1146			Total:       total,
1147			Note:        note,
1148			Allocations: allocs,
1149			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1150		}
1151		s.NextSeq++
1152		p.Seq = s.NextSeq
1153		s.Payments[payID] = p
1154	
1155		// 收款记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1156		// 一切不生效，该收款标识不被占用。
1157		if err := s.save(); err != nil {
1158			delete(s.Payments, payID)
1159			s.NextSeq--
1160			return err
1161		}
1162		fmt.Fprintf(stdout, "已登记收款 %q（总额 %d 分，%s）：\n", payID, total, moneyFen(total))
1163		printAllocationBalances(s, p, allocs)
1164		fmt.Fprintln(stdout)
1165		printPayment(p, s)
1166		return nil
1167	}
