1169	// samePaymentContent 按客户、总额、备注与月份-金额对应关系判定两笔收款
1170	// 内容相同；分配顺序不影响身份。判重依据首次登记内容，不受后续更正影响。
1171	func samePaymentContent(p *payment, customerID string, total int64, note string, allocs []paymentAllocation) bool {
1172		if p.CustomerID != customerID || p.Total != total || p.Note != note {
1173			return false
1174		}
1175		return sameAllocations(p.Allocations, allocs)
1176	}
