1178	// sameAllocations 判定两个分配列表的月份-金额对应关系相同（顺序无关）。
1179	func sameAllocations(a, b []paymentAllocation) bool {
1180		if len(a) != len(b) {
1181			return false
1182		}
1183		for _, al := range b {
1184			if allocAmountFor(a, al.Month) != al.Amount {
1185				return false
1186			}
1187		}
1188		return true
1189	}
