1191	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
1192	func formatAllocations(allocs []paymentAllocation) string {
1193		parts := make([]string, len(allocs))
1194		for i, al := range allocs {
1195			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1196		}
1197		return strings.Join(parts, ",")
1198	}
