1211	func cmdBillUnpay(dir, payID, reason string) error {
1212		if strings.TrimSpace(payID) == "" {
1213			return fmt.Errorf("收款标识不能为空")
1214		}
1215		if strings.TrimSpace(reason) == "" {
1216			return fmt.Errorf("撤销原因不能为空")
1217		}
1218	
1219		s, err := loadStore(dir)
1220		if err != nil {
1221			return err
1222		}
1223		p, ok := s.Payments[payID]
1224		if !ok {
1225			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1226		}
1227	
1228		if p.Revoked {
1229			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1230			// 改用其他原因则拒绝。
1231			if p.RevokeReason == reason {
1232				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1233				printPayment(p, s)
1234				return nil
1235			}
1236			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1237		}
1238	
1239		// 首次退款后该收款的最新分配固定，拒绝整笔撤销；退款记录永久保留且
1240		// 不可撤销，实收按扣除退款后的余额继续计算。无退款的收款仍按原规则
1241		// 处理。
1242		if paymentHasRefunds(s, payID) {
1243			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝整笔撤销；如需退回余款请继续登记部分退款", payID)
1244		}
1245	
1246		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1247		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1248		// 分配、更正与撤销原因永久保留。
1249		p.Revoked = true
1250		p.RevokeReason = reason
1251		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1252		s.NextSeq++
1253		p.RevokeSeq = s.NextSeq
1254	
1255		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1256		if err := s.save(); err != nil {
1257			p.Revoked = false
1258			p.RevokeReason = ""
1259			p.RevokedAt = ""
1260			p.RevokeSeq = 0
1261			s.NextSeq--
1262			return err
1263		}
1264		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1265		printAllocationBalances(s, p, currentAllocations(s, p))
1266		fmt.Fprintln(stdout)
1267		printPayment(p, s)
1268		return nil
1269	}
