1311	// --- 收款分配更正 ---
1312	
1313	func cmdBillCorrect(dir, payID, corrID, reason string, allocArgs []string) error {
1314		if strings.TrimSpace(payID) == "" {
1315			return fmt.Errorf("收款标识不能为空")
1316		}
1317		if strings.TrimSpace(corrID) == "" {
1318			return fmt.Errorf("更正标识不能为空")
1319		}
1320		if strings.TrimSpace(reason) == "" {
1321			return fmt.Errorf("更正原因不能为空")
1322		}
1323		allocs, err := parseAllocations(allocArgs)
1324		if err != nil {
1325			return err
1326		}
1327		// 分配顺序不影响更正身份：统一按月份升序保存与比较。
1328		sort.Slice(allocs, func(i, j int) bool { return allocs[i].Month < allocs[j].Month })
1329	
1330		s, err := loadStore(dir)
1331		if err != nil {
1332			return err
1333		}
1334		p, ok := s.Payments[payID]
1335		if !ok {
1336			return fmt.Errorf("收款标识 %q 不存在，无法更正分配", payID)
1337		}
1338	
1339		if existing, ok := s.Corrections[corrID]; ok {
1340			// 相同标识按目标收款、原因与新月份-金额对应关系判重（列表顺序无关）：
1341			// 内容相同返回原更正记录，不改分配、不增历史；后续更正或收款撤销
1342			// 不影响此规则。任何一项不同（含跨收款复用）均拒绝。
1343			if existing.PaymentID == payID && existing.Reason == reason && sameAllocations(existing.Allocations, allocs) {
1344				fmt.Fprintf(stdout, "更正 %q 已存在且内容相同，返回原更正记录（不改分配、不增历史）：\n\n", corrID)
1345				printCorrection(existing, s)
1346				return nil
1347			}
1348			return fmt.Errorf("更正标识 %q 已存在但内容不同（已有：收款=%s 原因=%q 新分配=%s），拒绝复用",
1349				corrID, existing.PaymentID, existing.Reason, formatAllocations(existing.Allocations))
1350		}
1351	
1352		// 新增更正只允许未撤销收款。
1353		if p.Revoked {
1354			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），不能新增分配更正", payID, p.RevokeReason)
1355		}
1356	
1357		// 首次退款后该收款的最新分配固定，拒绝新增分配更正；已有更正的相同
1358		// 重放已在上面按原记录返回，不受此限。无退款的收款仍按原规则处理。
1359		if paymentHasRefunds(s, payID) {
1360			return fmt.Errorf("收款 %q 已发生退款，最新分配已固定，拒绝新增分配更正", payID)
1361		}
1362	
1363		// 新分配合计必须等于原收款总额（不重复收钱也不多收），全程整数运算。
1364		var sum int64
1365		for _, al := range allocs {
1366			sum, err = add64(sum, al.Amount)
1367			if err != nil {
1368				return fmt.Errorf("新分配金额合计溢出有符号 64 位整数范围，拒绝更正")
1369			}
1370		}
1371		if sum != p.Total {
1372			return fmt.Errorf("新分配合计 %d 分与原收款 %q 的总额 %d 分不一致，拒绝更正", sum, payID, p.Total)
1373		}
1374		// 新分配月份须是原客户的已结算账单。
1375		for _, al := range allocs {
1376			if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
1377				return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算），更正只能分配到已存在账单", p.CustomerID, al.Month)
1378			}
1379		}
1380	
1381		// 以当前最新分配为起点：撤去该笔当前分配再计入新分配后，涉及月份
1382		// 均须满足 0 ≤ 实收 ≤ 应付；其他收款不变，全部合法才整笔生效。
1383		current := currentAllocations(s, p)
1384		for _, m := range unionMonths(current, allocs) {
1385			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1386			_, payable, err := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1387			if err != nil {
1388				return fmt.Errorf("客户 %s 的 %s 当前应付异常，拒绝更正: %w", p.CustomerID, m, err)
1389			}
1390			received, err := paymentReceived(s, p.CustomerID, m)
1391			if err != nil {
1392				return fmt.Errorf("客户 %s 的 %s 实收累计异常，拒绝更正: %w", p.CustomerID, m, err)
1393			}
1394			// 该笔收款未撤销，其实收必然包含当前分配，撤去不会变负。
1395			received -= allocAmountFor(current, m)
1396			received, err = add64(received, allocAmountFor(allocs, m))
1397			if err != nil {
1398				return fmt.Errorf("客户 %s 的 %s 更正后实收溢出有符号 64 位整数范围，拒绝更正", p.CustomerID, m)
1399			}
1400			if received > payable {
1401				return fmt.Errorf("更正后客户 %s 的 %s 实收 %d 分将超过当前应付 %d 分，拒绝更正；全部状态保持不变",
1402					p.CustomerID, m, received, payable)
1403			}
1404		}
1405	
1406		c := &correction{
1407			ID:          corrID,
1408			PaymentID:   payID,
1409			Reason:      reason,
1410			Allocations: allocs,
1411			CreatedAt:   time.Now().UTC().Format(time.RFC3339),
1412		}
1413		s.NextSeq++
1414		c.Seq = s.NextSeq
1415		s.Corrections[corrID] = c
1416	
1417		// 更正记录、序号与余额状态在同一次原子保存中持久化；保存失败则
1418		// 一切不生效，该更正标识不被占用。
1419		if err := s.save(); err != nil {
1420			delete(s.Corrections, corrID)
1421			s.NextSeq--
1422			return err
1423		}
1424		fmt.Fprintf(stdout, "已登记收款分配更正 %q（关联收款 %q）：\n\n", corrID, payID)
1425		printCorrection(c, s)
1426		return nil
1427	}
1428	
1429	// unionMonths 返回两个分配列表涉及月份的并集，按月份升序。
1430	func unionMonths(a, b []paymentAllocation) []string {
1431		set := make(map[string]bool, len(a)+len(b))
1432		for _, al := range a {
1433			set[al.Month] = true
1434		}
1435		for _, al := range b {
1436			set[al.Month] = true
1437		}
1438		months := make([]string, 0, len(set))
1439		for m := range set {
1440			months = append(months, m)
1441		}
1442		sort.Strings(months)
1443		return months
1444	}
1445	
1446	// allocationBefore 返回一次更正发生前该收款生效的分配：上一条更正的
1447	// 新分配，或（首次更正时）收款的原始分配。
1448	func allocationBefore(s *state, c *correction) []paymentAllocation {
1449		before := s.Payments[c.PaymentID].Allocations // 载入时已校验存在
1450		var latest *correction
1451		for _, o := range s.Corrections {
1452			if o.PaymentID == c.PaymentID && o.Seq < c.Seq && (latest == nil || o.Seq > latest.Seq) {
1453				latest = o
1454			}
1455		}
1456		if latest != nil {
1457			before = latest.Allocations
1458		}
1459		return before
1460	}
1461	
1462	// printCorrection 输出单笔更正记录：关联收款、标识、原因、完整前后分配，
1463	// 以及前后分配涉及月份的当前余额。
1464	func printCorrection(c *correction, s *state) {
1465		p := s.Payments[c.PaymentID] // 载入时已校验存在
1466		before := allocationBefore(s, c)
1467		fmt.Fprintf(stdout, "更正标识：%s\n", c.ID)
1468		fmt.Fprintf(stdout, "关联收款：%s（客户 %s，总额 %d 分（%s），备注：%s）\n",
1469			p.ID, p.CustomerID, p.Total, moneyFen(p.Total), p.Note)
1470		fmt.Fprintf(stdout, "原因：%s\n", c.Reason)
1471		fmt.Fprintf(stdout, "更正前分配：%s\n", formatAllocations(before))
1472		fmt.Fprintf(stdout, "更正后分配：%s\n", formatAllocations(c.Allocations))
1473		fmt.Fprintln(stdout, "涉及月份当前余额：")
1474		for _, m := range unionMonths(before, c.Allocations) {
1475			b := s.Bills[billKey(p.CustomerID, m)] // 载入时已校验存在
1476			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, m))
1477			received, _ := paymentReceived(s, p.CustomerID, m)
1478			fmt.Fprintf(stdout, "  月份 %s：本笔分配 %d 分 → %d 分；当前应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1479				m, allocAmountFor(before, m), allocAmountFor(c.Allocations, m),
1480				payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1481		}
1482	}
1483	
1484	// --- 账后对账流水 ---
1485	
1486	// ledgerEvent 是某张已结算账单账后流水中的一个事件：调整、撤销调整、收款、
1487	// 分配更正、撤销收款或退款。事件按全局操作序号升序回放；撤销在其发生序号抵消
1488	// 对应原操作，已撤销记录在撤销之前仍计入，不按当前撤销状态删除原事件；
1489	// 更正在其发生序号把关联收款在本账单的分配由前值替换为后值；退款在其发生
1490	// 序号减少本账单实收，不可撤销。
1491	type ledgerEvent struct {
1492		seq           int64  // 全局操作序号（调整/收款/更正/退款及其撤销共用）
1493		kind          string // 事件类型：调整 / 撤销调整 / 收款 / 更正 / 撤销收款 / 退款
1494		refID         string // 原记录标识（调整标识、收款标识或更正标识）
1495		deltaPayable  int64  // 对当前应付的影响（分，带符号）
1496		deltaReceived int64  // 对实收的影响（分，带符号）
1497		note          string // 原因（调整/更正类）或备注（收款类）
1498		linkSeq       int64  // 撤销事件关联的原操作序号；非撤销事件为 0
1499		payTotal      int64  // 收款类事件：汇款总额
1500		payAlloc      int64  // 收款类事件：本账单分配（撤销收款事件为被取消的最新分配；退款事件为本账单退款额）
1501		payID         string // 更正/退款事件：关联收款标识
1502		beforeAlloc   int64  // 更正事件：本账单更正前分配
1503		afterAlloc    int64  // 更正事件：本账单更正后分配
1504		afterPayable  int64  // 事件后的应付（回放时填充）
1505		afterReceived int64  // 事件后的实收（回放时填充）
1506	}
1507	
1508	// billLedger 返回目标账单的一条按操作序号升序的账后流水，事件之后的三项
1509	// 余额已逐步填充。业务归属、金额影响（调整/撤销/收款/更正/撤销收款/退款）
1510	// 与完整性核验都来自与 bill reconcile 共用的 postbill 计算，本处只取该账单
1511	// 那一条流水：
1512	//
1513	//   - 以原总金额为初始应付、零实收为起点；
1514	//   - 回放覆盖完整流水（不受查询截止序号限制），序号重复、撤销先于原操作，
1515	//     或任一事件之后不满足 0 ≤ 实收 ≤ 应付 ≤ 有符号 64 位最大值，都视为
1516	//     数据异常并拒绝，即使异常发生在截止序号之后——只检查最终余额会放过
1517	//     中间越界的存档；
1518	//   - 曾涉及该账单的收款在被更正移出该月后，仍保留零金额撤销事件。
1519	//
1520	// 只读：不修改库、不占用序号、不新增记录。
1521	func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
1522		ops, err := postbillOps(s, b.CustomerID)
1523		if err != nil {
1524			return nil, err
1525		}
1526		ledgers, err := verifyPostbillLedgers(ops, []*bill{b})
1527		if err != nil {
1528			return nil, err
1529		}
1530		return ledgers[b.Month], nil
1531	}
1532	
1533	func cmdBillLedger(dir, customerID, month, cutoffText string, hasCutoff bool) error {
1534		if !validMonth(month) {
1535			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
1536		}
1537		s, err := loadStore(dir)
1538		if err != nil {
1539			return err
1540		}
1541		cust, ok := s.Customers[customerID]
1542		if !ok {
1543			return fmt.Errorf("客户标识 %q 不存在", customerID)
1544		}
1545		b, ok := s.Bills[billKey(customerID, month)]
1546		if !ok {
1547			return fmt.Errorf("客户 %s 的 %s 尚无账单（未结算）", customerID, month)
1548		}
1549	
1550		// 截止序号使用调整/收款/更正/退款及其撤销共用的已保存全局序号：省略表示最新，
1551		// 0 只返回初始余额，截止包含该序号；因其他客户或月份操作造成的序号
1552		// 空档合法。负数、非整数或超过存档全局序号上限一律拒绝。
1553		cutoff := s.NextSeq
1554		cutoffDesc := "省略，按最新"
1555		if hasCutoff {
1556			v, perr := strconv.ParseInt(strings.TrimSpace(cutoffText), 10, 64)
1557			if perr != nil {
1558				return fmt.Errorf("截止操作序号 %q 不是非负整数: %w", cutoffText, perr)
1559			}
1560			if v < 0 {
1561				return fmt.Errorf("截止操作序号不能为负数，收到 %d", v)
1562			}
1563			if v > s.NextSeq {
1564				return fmt.Errorf("截止操作序号 %d 超过存档全局序号上限 %d", v, s.NextSeq)
1565			}
1566			cutoff = v
1567			cutoffDesc = "指定"
1568		}
1569	
1570		// 先核验目标账单的完整流水：任何异常（即使发生在截止序号之后）都
1571		// 拒绝，不输出部分正常的报告。
1572		events, err := billLedger(s, b)
1573		if err != nil {
1574			return err
1575		}
1576		printBillLedger(b, cust, s.NextSeq, cutoff, cutoffDesc, events)
1577		return nil
1578	}
1579	
1580	func printBillLedger(b *bill, cust *customer, nextSeq, cutoff int64, cutoffDesc string, events []ledgerEvent) {
1581		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
1582		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
1583		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
1584		fmt.Fprintf(stdout, "原总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
1585		fmt.Fprintf(stdout, "存档全局序号上限：%d\n", nextSeq)
1586		fmt.Fprintf(stdout, "截止操作序号：%d（%s）\n", cutoff, cutoffDesc)
1587		fmt.Fprintf(stdout, "初始余额：应付 %d 分（%s），实收 0 分（%s），未收余额 %d 分（%s）\n",
1588			b.TotalFee, moneyFen(b.TotalFee), moneyFen(0), b.TotalFee, moneyFen(b.TotalFee))
1589	
1590		// 截止包含该序号；截止之后的事件（含撤销）既不出现也不影响历史余额。
1591		payable, received := b.TotalFee, int64(0)
1592		var shown []ledgerEvent
1593		for _, ev := range events {
1594			if ev.seq > cutoff {
1595				continue
1596			}
1597			shown = append(shown, ev)
1598			payable, received = ev.afterPayable, ev.afterReceived
1599		}
1600		if len(shown) == 0 {
1601			fmt.Fprintln(stdout, "流水：无（截止序号以内该账单无账后事件）")
1602		} else {
1603			fmt.Fprintln(stdout, "流水（按操作序号升序）：")
1604			for i, ev := range shown {
1605				fmt.Fprintf(stdout, "  %d. %s\n", i+1, formatLedgerEvent(ev))
1606			}
1607		}
1608		fmt.Fprintf(stdout, "截止时余额：应付 %d 分（%s），实收 %d 分（%s），未收余额 %d 分（%s）\n",
1609			payable, moneyFen(payable), received, moneyFen(received), payable-received, moneyFen(payable-received))
1610	}
1611	
1612	// formatLedgerEvent 渲染一条流水事件：序号、类型、原记录标识、金额影响、
1613	// 原因或备注、撤销关联，以及事件后的应付、实收、未收余额；收款类事件同时
1614	// 说明汇款总额与本账单分配。
1615	func formatLedgerEvent(ev ledgerEvent) string {
1616		after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
1617			ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
1618		switch ev.kind {
1619		case "调整":
1620			return fmt.Sprintf("序号 %d 调整 %s：应付 %+d 分（%s，%s），原因：%s → %s",
1621				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
1622		case "撤销调整":
1623			return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %+d 分（%s，关联序号 %d 的调整 %s），原因：%s → %s",
1624				ev.seq, ev.refID, ev.deltaPayable, moneyFen(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
1625		case "收款":
1626			return fmt.Sprintf("序号 %d 收款 %s：实收 %+d 分（%s，汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
1627				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
1628		case "更正":
1629			return fmt.Sprintf("序号 %d 更正 %s：实收 %+d 分（%s，关联收款 %s，本账单分配 %d 分 → %d 分），原因：%s → %s",
1630				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.beforeAlloc, ev.afterAlloc, ev.note, after)
1631		case "退款":
1632			return fmt.Sprintf("序号 %d 退款 %s：实收 %+d 分（%s，关联收款 %s，本账单退款 %d 分），原因：%s → %s",
1633				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.payID, ev.payAlloc, ev.note, after)
1634		default: // 撤销收款
1635			return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %+d 分（%s，关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
1636				ev.seq, ev.refID, ev.deltaReceived, moneyFen(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
1637		}
1638	}
1639

